    "body": "【主线】小鼠最常用的是 70% 部分肝切除（PHx，切除左外叶与中叶，保留右叶与尾状叶）。切除后残肝在数小时内就被推入细胞周期：0-1 小时是即时早期基因（IEG）窗口，JUN、FOS、EGR1、ATF3、MYC 不需要新蛋白合成就能被转录，同时 IL-6 经 gp130 激活 STAT3、TNF 经 TNFRSF1A 激活 NF-κB，这一步叫启动（priming），作用是让肝细胞对生长因子变得敏感。2-6 小时进入 G1，CCND1 上升、RB 被磷酸化。12-24 小时开始 DNA 合成，BrdU/EdU 标记指数在 24-48 小时达峰（小鼠偏晚、大鼠偏早）。48-72 小时出现有丝分裂高峰，随后细胞肥大与基质重建接棒，一周左右恢复大部分质量。\n\n【关键】把再生理解成三段：启动靠细胞因子（IL-6/STAT3、TNF/NF-κB），增殖靠生长因子（HGF-MET、EGF 家族、TGFα、HB-EGF），终止靠 TGF-β1、IL-1 与 YAP 活性回落。还有一个容易被忽略的变量：切除比例决定了同步化程度，切得太少几乎不触发，切 70% 才能得到整齐的一波。人肝再生比啮齿类慢得多，是以周到月计的，写文章时别把小鼠的 48 小时直接搬到人身上。\n\n【和生信分析的连接】看到「再生」数据集第一件事是对齐时间点。如果把照后 24 小时和 72 小时混在一个比较里，DNA 合成峰与有丝分裂峰会让 CCNB1、CCND1 出现方向矛盾的结论——不是数据错，是时间窗错。建议先算 IEG 评分（JUN、FOS、EGR1、ATF3）判断样本落在启动期还是增殖期，再用 MKI67、TOP2A、PCNA 判断增殖强度。另外 sham 手术对照必不可少：开腹本身就会诱导一批应激基因。",
