    "body": "【主线】肝小叶的血流从门静脉与肝动脉汇入，经肝窦流向中央静脉。沿途氧分压、激素浓度、胆汁酸浓度都在变，于是肝细胞被分成三个区。zone 1（门静脉周围）氧最足，主攻耗氧的合成与解毒前置步骤：糖异生（PCK1、G6PC）、尿素循环（CPS1、ASS1、OTC）、β 氧化与氨基酸代谢。zone 3（中央静脉周围）氧最低，主攻糖酵解（GCK、PKLR）、脂质合成（FASN、SCD1）、谷氨酰胺合成（GLUL）、胆汁酸转运与 CYP 介导的药物代谢——所以对乙酰氨基酚过量伤的恰恰是 zone 3。\n\n【关键】分区不是基因突变出来的，而是位置信息算出来的：Wnt/β-catenin 在 zone 3 最活跃（见 regen-03），加上氧梯度经 HIF 通路、血流剪切力、以及中央静脉内皮分泌的 RSPO3/WNT2/WNT9B 共同塑形。因此 zone 身份是可逆的，损伤后残存细胞能「换岗」。临床上的对应现象是：zone 3 坏死见于缺血、酒精与对乙酰氨基酚损伤；zone 1 坏死见于磷中毒与早期缺血再灌注。\n\n【和生信分析的连接】分区评分是肝课题的高价值分析。可用现成肝脏分区基因集（如 Halpern 等的 zonation 列表）分别给 zone 1（CPS1、ASS1、PCK1、G6PC、SLC25A15）与 zone 3（GLUL、CYP2E1、OAT、SLC1A2、AXIN2）打分，再看照射后比值往哪边偏。若 zone 3 标志整体下滑而 zone 1 相对上升，提示中央静脉周围细胞丢失、残存的是门管区细胞。切记：单细胞做分区判断要看空间位置或排序推断，光凭表达谱容易把「去分化细胞」误判成另一个区。",
