    "body": "【主线】成熟肝细胞在强烈损伤下会下调成熟标志（ALB、HNF4A、CPS1），上调胎儿期与胆管相关基因（SOX9、KRT19、KRT7、EPCAM、OVOL1、SPINK1），形态变扁、极性丢失、增殖能力恢复。这个过程叫去分化，也有人叫肝细胞重编程或「类祖细胞化」。它不是终末转变，撤去损伤因素后多数细胞能重新分化回成熟表型，所以更像一种可逆的应激状态而非另一种细胞类型。\n\n【关键】驱动因素集中在几条轴上：YAP 持续激活（把细胞推向胎儿样、增殖态，见 regen-04）、TGF-β 与 Notch 联合（把肝细胞推向胆管方向）、以及炎症因子 IL-6 与氧化应激。关键转录因子是 SOX9 与 OVOL1/OVOL2，前者标记可塑性细胞，后者抑制成熟身份。要注意：SOX9 阳性不等于胆管细胞，肝细胞去分化与胆管细胞转分化在转录组上高度相似，这正是本课题最容易踩的坑。\n\n【和生信分析的连接】判断去分化要用「成熟度评分下降 + 祖细胞评分上升」双向证据（如 HNF4A、ALB、CPS1、TTR 降；SOX9、KRT19、EPCAM、PROM1 升），单看一侧容易把混入的胆管细胞当证据。区分真去分化与取样污染，可看拷贝数：肿瘤或克隆性增生会有整条染色体的 CNV 事件（inferCNV/CopyKAT），而正常去分化细胞基因组是平的。此外要去掉解离应激基因（JUN、FOS、HSPA1A）的干扰，否则「去分化」评分会被技术噪声抬高。",
