    "summary": "肝脏不是长回原来大小就停，而是按「功能需求」在停。",
    "body": "【主线】hepatostat 指的是肝脏把自身质量维持在体重比例附近的内在调节机制：切除后启动增殖，恢复后自动停止，移植一个过大的肝又会萎缩，过小的肝则会代偿性增大。这个双向调节说明传感器测的不是体积而是「功能负荷」——包括代谢通量、胆汁酸流量、血流剪切力与基质张力。\n\n【关键】终止信号至少四条同时起作用：一是 TGF-β1（主要由星状细胞与血小板释放），经 SMAD2/3 诱导 CDKN1A 使细胞退出周期；二是 IL-1 与 TNF 的后期炎症信号转为抑制；三是 ECM 重建带来的机械信号改变，整合素-黏着斑张力上升、Hippo 通路重新激活把 YAP 赶出核；四是 YAP/β-catenin 活性自然回落（见 regen-04）。此外还有接触抑制与「细胞数量感知」的成分。多信号冗余是有意的设计：少一条也不会失控，这也解释了为什么单一通路敲除往往只延长再生窗口而不是无限增生。\n\n【和生信分析的连接】研究里最常被问的问题是「这个样本再生到位了吗」。可用一组终止程序基因（TGFB1、SERPINE1、CDKN1A、CDKN2B、CTGF、AGTR1）做评分，配合增殖评分（MKI67、TOP2A）看两者是否出现「增殖高 + 终止低」的不匹配——若在照射组持续存在，提示再生受阻而非再生旺盛。另一个实操提醒：hepatostat 是按功能负荷调节的，所以体重、营养状态、胆汁酸池大小都会影响结果，临床队列里这些变量常缺失，做跨队列比较时要先声明这个局限。",
