    "summary": "基质不只是脚手架，它的硬度和配体会直接改写细胞的增殖决策。",
    "body": "【主线】正常肝脏的基质以 IV 型胶原与层粘连蛋白为主，质地软（kPa 量级很低）；损伤后成纤维细胞与星状细胞改产 I 型胶原与纤连蛋白（FN1），基质变硬。肝细胞通过整合素（主要是 α1β1、α5β1、α6β1、αVβ1）识别配体上的 RGD 等序列，胞内端连接桩蛋白与踝蛋白，聚成黏着斑，再招募 FAK（PTK2）与 SRC，下游走 PI3K-AKT 与 MAPK 促存活增殖，同时通过 Rho-ROCK 提高肌动蛋白张力。\n\n【关键】机械信号与 Hippo 是同一件事的两面：基质越硬、张力越大，YAP 越容易入核（见 regen-04、tme-05）。这就形成正反馈——硬基质促增殖，增殖与收缩又让基质更硬。另外基质还通过「储存生长因子」参与调控：HGF、VEGF、TGF-β 都能结合在基质上，被蛋白酶（MMP2/9、uPA）释放后才起作用，所以 MMP 活性决定了生长因子的可用性。\n\n【和生信分析的连接】转录组里能看到的整合素信号通常是「配体端」明显、受体端不明显：COL1A1、COL3A1、FN1、SPARC、POSTN、MMP2、MMP9、TIMP1 上调，而 ITGB1 这类受体本身几乎不变（表达调控在构象激活而非转录）。所以别拿 ITGB1 mRNA 判断整合素活性，应做配体-受体分析或看下游靶基因（CTGF、CCN1、LOX）。还要注意：纤维化评分升高既可能是修复也可能是病理，判断标准是看它是否伴随功能下降（ALB 降、胆红素升）。",
