    "domainName": "肝脏再生",
    "title": "再生的表观遗传层：染色质先开门，基因才谈得上表达",
    "level": "前沿",
    "tags": [
      "表观遗传",
      "染色质可及性",
      "增强子",
      "先锋因子"
    ],
    "summary": "转录因子进不了关着的染色质，所以再生第一步是「开门」。",
    "body": "【主线】再生早期，一批基因的启动子与增强子从关闭变为可及，这个过程先于转录发生。推动开门的是先锋因子（pioneer factor）与染色质重塑复合物：FOXA1/2 在肝脏里被称为先锋因子，能结合在核小体缠绕的 DNA 上并把染色质撬开；SWI/SNF（ARID1A、SMARCA4）负责核小体滑动；组蛋白修饰酶负责加标记——H3K27ac 标记活跃增强子，H3K4me1 标记预备增强子，H3K27me3 标记被 Polycomb 压制的区域。\n\n【关键】YAP 的作用有一部分是表观遗传的：它入核后与 TEAD 结合，招募 BRD4 与 Mediator，把超级增强子激活（见 regen-04）。这也解释了为什么 BET 抑制剂（如 JQ1）能抑制 YAP 驱动的增殖。另一个重要机制是代谢物影响表观修饰：乙酰辅酶 A 决定乙酰化水平，S-腺苷甲硫氨酸决定甲基化，α-酮戊二酸影响去甲基化酶活性，所以再生期的代谢切换与表观重编程是耦合的。\n\n【和生信分析的连接】转录组里看不到染色质状态，只能看「表观调控因子」的表达（EZH2、KDM6A、BRD4、ARID1A、SMARCA4、HDAC1/2），这只能算间接证据。若课题有 ATAC-seq 或 CUT&Tag 数据，标准流程是先做差异可及区域，再与差异表达基因做交集，最后做 motif 富集（HOMER、chromVAR）推测是哪个转录因子在开门。纯 RNA 数据里更实用的替代是指标基因签名：Polycomb 靶基因（H3K27me3 相关）整体升高常提示去抑制。",
    "keyPoints": [
      "再生早期染色质先开放，FOXA1/2 是肝脏的先锋因子",
      "H3K27ac 标活跃增强子，H3K4me1 标预备增强子，H3K27me3 标抑制",
      "YAP-TEAD 招募 BRD4 激活超级增强子，这是 BET 抑制剂的依据",
      "代谢物（乙酰辅酶 A、SAM、α-酮戊二酸）直接决定表观修饰水平"
    ],
    "testYourself": "RNA-seq 里看到 EZH2 升高，能推断 H3K27me3 水平升高吗？中间缺哪些环节？",
