    "body": "【主线】损伤后最早响应的不是肝细胞而是免疫细胞。Kupffer 细胞（肝内常驻巨噬细胞，标志 CLEC4F、MARCO、CD68）被 DAMP（HMGB1、ATP、线粒体 DNA）激活，释放 IL-6、TNF、IL-1β，这一步是启动期的必要条件（见 regen-17）。补体系统同时被激活，C3a 与 C5a 通过受体 C3AR1/C5AR1 直接刺激肝细胞与星状细胞，C5a 还招募中性粒细胞。中性粒细胞随后涌入，用 NADPH 氧化酶产 ROS 清除碎片，但过量会扩大损伤——这就是「必要但过量有害」的典型。\n\n【关键】巨噬细胞在再生中要做三次换岗：早期促炎（M1 样，iNOS 高）、中期促增殖（分泌 HGF、WNT2、WNT3A，清除凋亡碎片）、后期促修复/抗炎（M2 样，ARG1、CD206 高）。这个时序如果错位——比如促炎期拖太久——再生就会延迟并转向纤维化。另一个关键点是胞葬（efferocytosis）：巨噬细胞吞掉凋亡肝细胞后会主动转向抗炎表型，这是「清理即信号」的机制，涉及 MERTK（见 regen-06）。\n\n【和生信分析的连接】免疫细胞在 bulk 数据里会稀释肝细胞信号，所以要先把免疫模块（PTPRC、CD68、LYZ、AIF1、ITGAM）评分出来，判断样本的免疫浸润比例是否组间可比。单细胞层面可按 CLEC4F、MARCO、LYVE1 区分 Kupffer 与单核来源巨噬细胞（后者 CD163、S100A8/9 偏高），这两类在再生中的角色并不相同。特别提醒：M1/M2 是体外二分法，在体细胞常处中间态（见 cancer-04），不要硬套。",
