    "body": "【主线】第一条是同源重组（HR）：MRN 复合物（MRE11-RAD50-NBS1）先切除末端产生单链，RPA 包裹后被 BRCA2 替换成 RAD51 核蛋白丝，侵入姐妹染色单体寻找同源序列，以它为模板精确合成。限速点是 RAD51 装载，需要 BRCA1、PALB2、BRCA2 协作，且只在 S/G2 期有模板可用。第二条是经典非同源末端连接（c-NHEJ）：KU70/KU80（XRCC6/XRCC5）抓住断端，招募 DNA-PKcs（PRKDC），再由 XRCC4-LIG4 连接。全年可用、速度快，但会丢或加几个碱基。\n\n【关键】第三条是替代末端连接（alt-EJ，含微同源介导的 MMEJ）：由 PARP1 感知断端，经 MRE11 切除暴露微同源序列，再由 POLQ（Polθ）填补。它的出错率最高，是「最后手段」，但在 HR 缺陷细胞里被大量征用——这正是 PARP 抑制剂合成致死的机制基础（见 death-08）。三条路的平衡由 53BP1 与 BRCA1 的竞争决定：53BP1 促 NHEJ，BRCA1 促 HR 末端切除。\n\n【和生信分析的连接】判断样本偏向哪条路，可看基因表达的相对构成：HR 模块（BRCA1/2、RAD51、PALB2、ATM、CHEK2）、NHEJ 模块（XRCC5/6、PRKDC、LIG4、XRCC4）、alt-EJ 模块（PARP1、POLQ、MRE11A）。若 HR 模块整体低而 alt-EJ 高，提示 HR 缺陷表型（BRCAness），这类肿瘤对 PARP 抑制剂与铂类可能更敏感。必须强调：转录水平低不等于功能缺陷，真正的判定要靠 HRD 基因组瘢痕评分或功能实验（RAD51 灶点）。",
