    "body": "【主线】旁效应（bystander effect）指被照射细胞把损伤信号传给未照射的邻近细胞，表现为后者出现 DSB、染色体畸变、凋亡甚至衰老。传递介质包括条件培养基可转移的因子（TGF-β1、TNF、IL-8、一氧化氮、ROS）、外泌体（携带 miRNA 与损伤相关分子）以及缝隙连接（GJIC）的直接传递。远隔效应（abscopal effect）指局部照射后远处未照射病灶缩小，机制主要是免疫介导：照射诱导免疫原性细胞死亡，释放肿瘤抗原与 DAMP，激活 cGAS-STING 与树突状细胞，进而启动全身性 T 细胞应答（见 radio-16）。\n\n【关键】旁效应的临床含义是双刃的：在正常组织里它可能扩大损伤范围，解释为什么部分肝照射后未受照区域也出现功能异常；在肿瘤里它可能增加杀伤。远隔效应在临床上罕见，但一旦出现往往与免疫治疗联合有关——所以「放疗 + PD-1 抑制剂」的 rationale 正是把罕见的远隔效应变成可预期的效应。要记住因果链的关键环节是抗原呈递与 T 细胞浸润，而不是射线直接杀远处细胞。\n\n【和生信分析的连接】旁效应在转录组里的特征是：未照射区域出现 DNA 损伤应答（CDKN1A、GADD45A、MDM2）与炎性签名（IL6、CXCL8、NFKBIA）同时升高，却没有任何直接辐射剂量学解释。做剂量-效应分析时（见 radio-15），这类样本会成为离群点，别急着删——先确认取样位置与照射野的关系。远隔效应在数据上表现为「未照射病灶的免疫浸润升高（CD8A、GZMB、IFNG）而肿瘤增殖下降」，但单个病例的观察很容易被采样偏差误导。",
