    "body": "【主线】辐射诱导的衰老（RIS）是照后细胞的重要命运之一，尤其在中低剂量、p53 功能正常的细胞里常见。特征：形态变大扁平、SA-β-gal 阳性、p16（CDKN2A）与 p21 持续升高、出现衰老相关异染色质灶、DNA 损伤灶（γH2AX 焦点）长期不消退。这些细胞不再分裂，但代谢活跃，持续分泌 SASP：IL-6、IL-8、CXCL1/2、MMP1/3、IGFBP3/7、TGF-β。\n\n【关键】为什么重要：一是它把「急性损伤」转成「慢性炎症」，是放射性纤维化迁延不愈的机制之一（见 radio-19）；二是衰老细胞会通过 SASP 诱导邻近细胞也衰老（旁效应的一种，见 radio-12），形成扩散；三是衰老肿瘤细胞可能重新获得增殖能力（部分研究提示），构成复发来源。治疗思路对应两条：senolytic 清除衰老细胞，或 senomorphic 抑制 SASP（如 IL-6/JAK 抑制剂、NF-κB 抑制剂、mTOR 抑制剂）。\n\n【和生信分析的连接】RIS 最可靠的转录特征是「周期基因整体低 + SASP 高 + 损伤应答基因（CDKN1A、GADD45A）高」的三联征。注意 CDKN1A 不特异（任何 p53 激活都会升），应优先看 CDKN2A、SERPINE1、IGFBP7、IL6、CXCL8 的组合。另有一个实操陷阱：SASP 因子多为分泌蛋白，在 bulk 组织里会被周围细胞稀释，若样本中实质细胞占比组间差异大，SASP 评分会被系统性拉偏，需先做细胞组成校正。",
