    "body": "【主线】氨磷汀（amifostine，WR-2721）是含巯基的磷酸化前药，被组织表面的碱性磷酸酶去磷酸化后变成活性代谢物 WR-1065，后者可自由进入细胞。保护机制有四条：直接清除自由基、提供氢原子修复受损靶分子、与 DNA 结合形成保护构象、以及耗氧降低氧分压（这条反而是增敏的反面，说明它主要作用于正常组织）。\n\n【关键】选择性的来源是「正常组织碱性磷酸酶活性高、血供好、pH 偏碱，肿瘤组织酶活性低、pH 偏酸」，所以前药更多在正常组织里被激活。临床上它被批准用于头颈放疗中保护唾液腺、以及化疗的肾脏与骨髓保护。争议点有三：一是副反应明显（低血压、恶心呕吐），需平卧给药并监测血压；二是是否保护肿瘤尚无定论，理论上存在风险；三是在肝脏这类大器官的 RILD 预防中证据不足，多数指南不推荐常规使用。其他候选防护剂包括 GC4419（超氧化物歧化酶模拟物）、Toll 样受体激动剂与 ACE 抑制剂，多在研究中。\n\n【和生信分析的连接】做「放射防护/增敏药物」的老药新用筛选时，氨磷汀属于「正常组织保护」类，与「肿瘤增敏」类的评价方向相反：前者希望正常细胞抗氧化基因（GCLC、NQO1、HMOX1）上调、肿瘤中不上调；后者希望肿瘤内抗氧化能力下降。用 CMap/连接图谱思路筛选时，注意药物扰动签名有细胞类型特异性，直接反查容易得到假阳性（见 cancer-18）。剂量与给药时序（照射前多久）往往是决定成败的变量，纯计算无法替代。",
