    "body": "【主线】正常组织并发症概率（NTCP）模型的任务是：给定剂量分布，估计某并发症发生的概率。肝脏最常用的是 Lyman-Kutcher-Burman（LKB）模型，三个参数——TD50（50% 概率发生并发症的剂量）、n（体积效应，n 小说明是「并联器官」、局部受照也能代偿）、m（曲线陡度）。肝脏在功能上是并联器官，所以体积效应显著：受照体积比受照剂量更能决定风险，这解释了为什么「平均肝剂量」与「受照体积比例」都是核心约束参数。\n\n【关键】临床上的约束通常是组合式的：平均肝剂量上限、接受某剂量以上的体积占比、以及剩余功能性肝体积的下限。具体数值随分次方案、基础肝功能（Child-Pugh 分级）与是否联合化疗而变化，不能一概而论，引用时务必回原始文献与现行指南。更要紧的是这个概念：剂量约束是群体统计的结果，个体化风险还要叠加基础肝病、肝硬化程度、既往治疗史。把约束当成绝对红线或完全无视，都是错的。\n\n【和生信分析的连接】纯计算课题若要碰剂量-效应，标准做法是把剂量学参数与生物学参数放在同一个模型里：前者如平均肝剂量、Vx；后者如影像组学特征或炎症/纤维化基因评分。样本量小的时候（见 stats-03），变量个数必须严格限制，且要先做共线性诊断——平均肝剂量与 Vx 高度相关，同时入模会不稳定。另一个常见错误是用 NTCP 预测值当作结局变量再做回归，这属于循环论证。最后一点：剂量约束的数值来自特定的技术与分次方案，换用新技术后必须重新校准，不能照抄旧指南。",
