    "body": "【主线】放射敏感性存在个体差异，极端例子是遗传性肿瘤易感综合征患者（如共济失调毛细血管扩张症，ATM 双等位基因失活）对射线极度敏感。在普通人群里，差异更多来自常见变异的累加效应，候选基因集中在三类：DNA 损伤修复（ATM、BRCA1/2、XRCC1、XRCC3、LIG4、RAD51）、细胞因子与纤维化（TGFB1、TNF、IL6、IL1A）、以及氧化应激（GSTM1、GSTP1、SOD2、CAT）。\n\n【关键】研究范式叫放疗基因组学（radiogenomics）：用 GWAS 找与放射性损伤相关的 SNP，目标是建立预测模型以个体化调整剂量。现实进展有限，原因有三：一是表型定义不统一（RILD 的诊断标准本身就有版本差异，见 radio-06）；二是样本量小、效应量小；三是剂量学与临床因素的解释力往往强于遗传因素，加了 SNP 提升有限。所以目前遗传标记不能用于临床决策，只能作为机制线索。\n\n【和生信分析的连接】这类课题最实用的落点是「把种系变异与表达联系起来」：用 eQTL 数据看某个 SNP 是否影响 ATM、TGFB1 等基因的表达，再用 MR 思路检验「表达量→放射敏感性表型」的方向（见 method-08）。注意 MR 在这里的难点是暴露（基因表达）与结局（RILD）都难有大型 GWAS，工具变量往往很弱（见 method-16）。另一个务必避免的错误：把肿瘤组织的体细胞突变当作放射敏感性标志——那是肿瘤的基因组，不是正常组织的修复能力。",
