    "body": "【主线】肝是并联器官，能耐受局部高剂量但怕大体积受照（见 radio-15）。立体定向体部放疗（SBRT）的思路正是利用这一点：用多角度共面/非共面束把高剂量精确堆在靶区，让剂量在靶区外快速跌落，使高剂量区体积很小。代价是单次剂量大，对晚反应组织（α/β 低）的生物学效应更强（见 radio-10），所以分次方案的设计比总剂量更考究。\n\n【关键】粒子治疗的价值也在这里：质子 Bragg 峰后剂量骤降，能减少肿瘤后方与周边正常肝的积分剂量；碳离子还叠加更高的 RBE 与对缺氧不敏感（见 radio-09）。对靠近胃肠、肝门或大血管的病灶，粒子治疗可能把「不可治」变成「可治」。但要注意不确定性：粒子射程对组织密度与解剖变化敏感，摆位误差、呼吸运动、肠道气体都会改变实际剂量分布，所以常需更大边界或实时影像引导——这又抵消了一部分物理优势。\n\n【和生信分析的连接】这类课题若做疗效预测，结局变量通常是局部控制率与总生存，而非基因表达差异。可以把剂量学参数（靶区剂量、正常肝受照体积）与生物学特征（缺氧签名、增殖签名、免疫浸润）做交互项分析，检验「生物学特征是否修饰剂量-效应关系」。样本量小时交互项极易过拟合，建议预先指定一两个假设再检验，而不是穷举。另外别忽略时间因素：SBRT 后影像学改变的判读窗口与 RILD 的发生时相重叠（见 radio-06），结局定义必须写清楚。如果把放射性坏死误判为进展，会系统性低估局部控制率。",
