    "body": "【主线】经典路径是：慢性肝炎（HBV/HCV 感染、酒精、代谢功能障碍相关脂肪性肝病）→ 反复肝细胞损伤与再生 → 纤维化 → 肝硬化 → 异型增生结节 → 早期 HCC → 进展期 HCC。核心机制有两个：一是每次再生都是一次复制，复制越多突变越多；二是慢性炎症制造 ROS 与 NO，直接造成 DNA 损伤并抑制修复，等于同时踩油门和松刹车。HBV 还有特殊机制：病毒 DNA 可整合进宿主基因组，造成插入突变与基因组不稳定，即使不引起明显炎症也能致癌（如整合导致 TERT 附近重排）。\n\n【关键】黄曲霉毒素 B1 是重要的协同因素，它经 CYP450 活化成环氧化物，在 TP53 上打出一个特征性热点突变（R249S），这是分子流行病学的经典证据。病理上还有一条完全不同的路径：约一部分 HCC 发生在非肝硬化的正常肝背景下，多与 CTNNB1 激活突变相关，预后相对较好——这说明「HCC」不是一种病，而是多种病因、多种分子路径的集合（见 cancer-17）。\n\n【和生信分析的连接】做 HCC 研究必须处理病因混杂：HBV、HCV、酒精、MASLD 的转录组差异很大，直接合并会让差异基因变成「病因差异」而不是「癌与非癌差异」。做法是拿到临床注释后先按病因分层，或把病因作为协变量。另一个实用点：判断样本是否来自癌变早期，可看「再生/干细胞」评分与「成熟肝细胞」评分的比例，早期常保留较多成熟表型。若要做癌前病变研究，注意异型增生结节样本极难获取，多数公共数据集里没有。",
