    "body": "【主线】最常突变的是 TERT 启动子（约半数 HCC，是已知最常见的体细胞改变，导致端粒酶重新激活、细胞获得永生化能力），其次是 TP53（与 HBV、黄曲霉毒素相关，预后差）、CTNNB1（β-catenin 激活突变，对应 Wnt 型，常见于 HCV 与非肝硬化肝）、ARID1A 与 ARID2（染色质重塑复合物 SWI/SNF 成员）、AXIN1（Wnt 通路负调控因子，与 CTNNB1 突变互斥且后果不同）。\n\n【关键】要区分两类 Wnt 改变：CTNNB1 激活突变造成「干净」的 Wnt 激活（靶基因如 GLUL、LGR5、AXIN2 高），免疫上多为「冷」表型；AXIN1 失活造成的 Wnt 激活更杂乱，且常伴免疫浸润与预后不良。这个差别在纯计算里非常实用——同样是 Wnt 靶基因高，背后的分子亚型不同，免疫微环境也不同。其他值得记的：NFE2L2/KEAP1（抗氧化通路，见 radio-04）、FAT4、KMT2A/B、以及 IDH1/2 在胆管癌里更常见。\n\n【和生信分析的连接】判断驱动事件不能只看突变，要看「突变 + 表达 + 靶基因」三者是否一致。实操：一是从 MAF 数据统计高频基因并区分错义/截短/启动子突变（TERT 启动子突变常需专门注释，通用流程容易漏）；二是用 OncoKB/CIViC 或 VEP 注释致病性；三是把突变与通路活性评分交叉，例如 CTNNB1 突变样本应见 GLUL/LGR5 高、且免疫浸润低。注意 TCGA-LIHC 里病因以 HCV/酒精为主，与中国 HBV 为主的队列差异明显（见 cancer-17）。",
