    "body": "【主线】端粒是染色体末端的重复序列（TTAGGG）加保护蛋白复合物 shelterin（TRF1/2、POT1、TERF2IP）。DNA 聚合酶不能完整复制末端，所以每分裂一次端粒就短一截；短到临界长度时，裸露的末端被识别为 DSB，激活 ATM-p53 通路，细胞进入复制性衰老或凋亡。这道机制是抑癌屏障。癌细胞必须绕过它，主要两条路：重新激活端粒酶（TERT 启动子突变、MYC 扩增、TERT 重排），或启用替代性延长（ALT，基于同源重组，常见于部分肉瘤）。\n\n【关键】TERT 启动子突变有两个高频位点，产生新的转录因子结合位点，使 TERT 表达上调。它的特殊性在于「既是驱动事件又不改变蛋白序列」，所以全外显子测序常常漏掉——必须看启动子区域或全基因组。在 HCC 里，TERT 启动子突变往往是最早的事件之一，可在肝硬化前的异常增生结节中出现，因此被视为早期驱动。\n\n【和生信分析的连接】纯计算里判断端粒状态有几个层次：一是 TERT 表达（注意正常肝也有一定表达，肿瘤里升高幅度未必大）；二是端粒长度估计——可用 TelNet 或基于 WGS 的 telomere content 算法，但 RNA-seq 推断的可靠性有限；三是端粒维持相关签名（TERT、TERC、DKC1、NHP2、NOP10 相关模块）。要提醒的是：不要把「TERT 高表达」当成 ALT 阴性的证据，两条路可以并存于不同克隆。另外 TERT 表达受表观调控，mRNA 与端粒酶活性相关性并不强。",
