    "body": "【主线】肿瘤长大到一定体积就需要新血管，主信号是 VEGFA 结合 VEGFR1/2（FLT1/KDR），经 PLCγ-MAPK 促内皮增殖、经 PI3K-AKT 促存活，并上调 SRC 导致 VE-cadherin 磷酸化、血管通透性升高。此外还有 VEGFR2 之外的旁路：ANG-TIE2（见 regen-07）、DLL4-NOTCH（决定出芽时尖细胞与柄细胞的分工）、PDGFB-PDGFRB（招募周细胞）。\n\n【关键】肿瘤血管的特征是：结构扭曲、周细胞覆盖少、灌注不均、通透性高，结果是既供氧不足又让药物难进。抗 VEGF 治疗最初设想是「断粮」，但实际观察到的是「血管正常化窗口」——在合适剂量与时间窗内，血管结构暂时改善、灌注增加、药物递送变好、缺氧减轻，此时联合化疗或免疫治疗才最有效。剂量过大反而破坏血管、加重缺氧、促进侵袭与转移（这也是抗血管治疗耐药与矛盾效应的来源之一）。\n\n【和生信分析的连接】判断血管状态可用三组：内皮（PECAM1、CDH5、VWF、KDR）、周细胞（RGS5、PDGFRB、ACTA2 需排除 CAF）、血管生成活性（VEGFA、ANGPT2、DLL4、ESM1、SPARCL1 后者偏稳定）。注意「内皮基因高」不等于「血管多」，因为单细胞解离效率对内皮影响极大，跨样本比较绝对丰度很不可靠（见 method-23）。肿瘤内相对比较可以，跨数据集只能看方向。",
