    "summary": "肿瘤不是一群相同的细胞，而是一棵不断分叉、彼此竞争的进化树。",
    "body": "【主线】异质性分两层：克隆异质性（不同克隆携带不同驱动突变，源自基因组不稳定与选择压力）与表型异质性（同一克隆在不同微环境下表达谱不同，部分由表观与位置决定）。演化模式常用两种比喻：线性演化（一个克隆逐步累积突变并取代其他）与分支演化（多个克隆并存、各自适应不同微环境，治疗后在空隙中扩张）。治疗本身就是选择压力：靶向治疗杀死敏感克隆，耐药克隆扩张，这就是获得性耐药的群体基础。\n\n【关键】HCC 的异质性特别强，原因有三：肝脏血供复杂、肿瘤常多发且各自独立起源（多中心发生）、以及慢性炎症持续制造新突变。这解释了一个临床现象——同一个患者的不同结节可能有完全不同的分子分型，因此单点活检的代表性有限。另一个重要概念是「肿瘤干细胞」：一小群具自我更新与多向分化能力的细胞（标志常用 EPCAM、KRT19、PROM1/CD133、干性指数 mRNA 水平），它们对治疗耐受并驱动复发（见 cancer-16）。\n\n【和生信分析的连接】单细胞数据里推断克隆结构主要靠拷贝数：inferCNV（用免疫/基质细胞作参考，沿染色体看表达滑窗）或 CopyKAT。判读要点是：整条染色体臂级别的改变可信，小片段极不可靠；参考细胞选错会造出假 CNV。若要做克隆演化，把 CNV 谱聚类成克隆、再算各样本的克隆比例，配合突变数据（若有）构建系统树。表型异质性则用通路评分或 NMF 分解来刻画。特别注意：表型异质性高不等于克隆异质性高，两者常被混为一谈。",
