    "body": "【主线】肿瘤干细胞（CSC）假说认为肿瘤内只有一小部分细胞具自我更新与重建肿瘤的能力。肝癌里常用标志包括 EPCAM、KRT19、PROM1（CD133）、ALDHA1、以及侧群细胞特征。KRT19 阳性的 HCC 是一个被反复验证的亚型：侵袭性强、复发率高、对索拉非尼等治疗反应差，且常伴 TGF-β 与 Wnt 激活。\n\n【关键】现代观点更强调「干性是一种状态而非固定身份」：分化细胞在治疗压力或微环境信号（TGF-β、HGF、缺氧）下可获得干性特征，这叫可塑性。机制上核心是几条轴的叠加：Wnt/β-catenin 维持自我更新、YAP 促增殖与去分化（见 regen-04）、TGF-β 促 EMT 样转变（见 cancer-07）、以及表观重编程（见 regen-21）。这也是为什么单纯「杀 CSC」的策略效果有限——杀完了还能再生成。\n\n【和生信分析的连接】干性评分最常用的是 mRNAi 干性指数（基于机器学习在干细胞与分化细胞间训练的模型）或一组标志基因（EPCAM、KRT19、PROM1、ALDH1A1、SOX9、NANOG、POU5F1）。两个陷阱：一是 OCT4（POU5F1）与 NANOG 在体细胞中表达极低，测序噪声就能造成假阳性；二是干性评分与增殖评分高度相关，做多因素模型时会共线。建议同时报告干性评分与分化评分（ALB、HNF4A、CPS1）的比值，比单看一侧更能反映「去分化程度」。",
