    "id": "cancer-18",
    "domain": "cancer",
    "domainName": "肿瘤生物学",
    "title": "老药新用的计算逻辑：连接图谱、 signature 反转与靶点预测",
    "level": "前沿",
    "tags": [
      "药物重定位",
      "CMap",
      "签名反转",
      "靶点预测"
    ],
    "summary": "老药新用的计算本质：找能把疾病签名推回去的扰动签名。",
    "body": "【主线】主流思路有三类。第一类是签名反转（signature reversal）：疾病状态有一组上调/下调基因，若某药物的扰动签名与之方向相反，就推测该药可能纠正疾病表型；CMap/LINCS 是这类分析的数据基础（用细胞系加药后的表达谱建库）。第二类是靶点为中心：从差异基因或驱动事件反推可成药靶点（如受体酪氨酸激酶、表观酶），再用 DrugBank/ChEMBL 找已有药物。第三类是网络/通路层面：把疾病模块与药物靶点模块做重叠或邻近性分析。\n\n【关键】这类分析的共同弱点是「相关性不等于机制」：签名反转可能只是因为药物有普遍性细胞毒性（杀伤细胞后增殖基因集体下降，看起来就像「反转」）。所以必须做几个对照：一是排除细胞毒/增殖签名的主导效应；二是检验剂量与时间依赖性（真机制应呈单调关系）；三是看该药在独立数据集是否一致；四是用 MR 或共定位从遗传学角度验证靶点（见 method-08、method-18）。此外血药浓度能否达到实验浓度是常被忽略的一关。\n\n【和生信分析的连接】对本课题最实用的落点是「把放射损伤签名与药物扰动签名对接」：先定义放射性肝损伤的上调/下调模块（损伤 vs 对照，且排除增殖与急性期反应的主导），再查哪些药物的扰动签名反向匹配，最后按「是否有肝毒性、是否有临床安全性数据」排序。务必报告富集显著性、匹配基因数与方向一致性，而不是只给一个排名表。还要提醒：CMap 基于细胞系，肝细胞与免疫细胞的扰动反应差异很大，结论只能作为假设。",
    "keyPoints": [
      "签名反转是药物重定位的主流思路，CMap/LINCS 是数据基础",
      "普遍性细胞毒性会造成假反转，必须设对照排除",
      "剂量与时间依赖性、独立数据集一致性是必需的验证",
      "细胞系结论只能作为假设，需考虑血药浓度可达性"
    ],
    "testYourself": "一个药物在 CMap 里与疾病签名高度反向匹配，你要先排除哪种最常见的假象？",
