    "body": "【主线】晚期 HCC 的一线治疗以「抗 PD-L1/PD-1 抗体 + 抗 VEGF 抗体」或「免疫 + 酪氨酸激酶抑制剂」的联合为主，二线有多靶点 TKI 与免疫单药可选。为什么抗血管与免疫能协同：抗 VEGF 使肿瘤血管正常化、改善 T 细胞浸润、并减少由 VEGF 介导的免疫抑制（VEGF 可抑制 DC 成熟、促进 Treg 与 MDSC）；免疫治疗则解除 T 细胞刹车（见 immune-04）。\n\n【关键】肝癌免疫治疗的特殊障碍有三：一是肝脏本身是免疫耐受器官（肝窦内皮、Kupffer 细胞、Treg 富集），二是多数 HCC 发生在肝硬化背景上，肝功能储备限制了治疗耐受性，三是病因相关免疫表型差异大（见 cancer-17）。所以疗效预测不能只看 PD-L1——HCC 的 PD-L1 表达常低且异质，判读价值有限；更有希望的是 T 细胞浸润与 IFN 签名、以及 ctDNA 动态（见 cancer-14）。另外要记住免疫治疗特有的不良反应：免疫相关肝炎在肝癌患者中尤其棘手，因为它与肿瘤进展、病毒再激活难以区分（见 radio-06 的鉴别思路）。\n\n【和生信分析的连接】做疗效相关的生信分析时，结局定义要写清是 ORR、PFS 还是 OS；不同终点的驱动因素不同。免疫联合的响应预测可组合：CD8 浸润（CD8A、GZMB）、IFN 签名（STAT1、CXCL9）、Treg/MDSC 比例（FOXP3、S100A8/9）、以及血管正常化相关（ANGPT1/2 比值）。小样本队列容易过拟合，建议用交叉验证并报告置信区间（见 method-24）。",
