    "summary": "铜死亡是铜直接黏在脂酰化蛋白上，把三羧酸循环的机器拧坏。",
    "body": "【主线】铜死亡（cuproptosis）是近年提出的一种调控性死亡方式，特征与凋亡、铁死亡、焦亡都不同：它依赖线粒体呼吸，形态上表现为线粒体皱缩、膜致密化，但不依赖 caspase，也不能被铁死亡或凋亡抑制剂挽救。分子链条是：铜离子载体（如 elesclomol）把铜带入细胞，FDX1 把 Cu²⁺ 还原成 Cu⁺（这一步是关键，FDX1 缺失会显著抵抗），Cu⁺ 直接结合三羧酸循环中脂酰化的酶——DLAT（二氢硫辛酰胺转乙酰酶）、DLST、PDHA1、PDHB——导致这些蛋白异常寡聚、铁硫簇蛋白丢失，代谢崩溃。\n\n【关键】「脂酰化」是这条通路的限定条件：脂酰化由 LIAS（硫辛酸合成酶）等催化，所以 LIAS 表达高的细胞更敏感，这也解释了为什么高度依赖线粒体呼吸的组织（肝、心、肾）更易受影响。铜稳态本身由 SLC31A1（CTR1）摄入、ATP7A/ATP7B 输出、MT1/MT2 螯合来维持，所以表达谱能部分预测敏感性。要注意区分「铜稳态紊乱导致的毒性」与「严格定义的铜死亡」——后者需要 FDX1 依赖、脂酰化依赖的证据。\n\n【和生信分析的连接】做铜死亡评分时，常被引用的基因集包含 FDX1、DLAT、DLST、PDHA1、PDHB、LIAS、LIPT1、GLS、CDKN2A 等，但不同文献列表差异很大，直接套用会得到不一致的结论。建议自己定义两组：核心执行（FDX1、LIAS、LIPT1、DLAT、DLST、PDHA1/PDHB）与铜转运/螯合（SLC31A1、ATP7A、ATP7B、MT1X、MT2A），前者高 + 后者低 → 提示易感。同时提醒：铜死亡在人体的生理相关性仍有争议，写作时不宜过度外推。",
