    "summary": "焦亡是边死边报警，孔一开内容物就成了炎症信号。",
    "body": "【主线】经典通路：模式识别受体（NLRP3、NLRC4、AIM2、Pyrin）感知 DAMP/PAMP 后组装炎症小体，招募 ASC 与 pro-caspase-1，caspase-1 自我激活后做两件事——把 pro-IL-1β、pro-IL-18 切成活性形式，以及切割 GSDMD。GSDMD 的 N 端片段结合膜上的酸性磷脂，聚成孔道，细胞肿胀破裂，同时释放 IL-1β/IL-18 与 HMGB1。非经典通路则由 caspase-4/5（人）或 caspase-11（鼠）直接识别胞质 LPS 后切 GSDMD。\n\n【关键】还有一条 GSDME（DFNA5）通路：caspase-3 在特定细胞中切割 GSDME 产生成孔片段，把「凋亡」转成「焦亡」——这是化疗药物引起组织损伤的机制之一，也解释了为什么同样剂量的化疗在某些组织里炎症特别重。焦亡的定位意义在于：它不是安静的死亡，而是主动释放免疫刺激信号（见 death-11），所以既能抗肿瘤也可能造成组织损伤。NLRP3 炎症小体的启动需要两个信号：第一信号由 TLR-NF-κB 上调 NLRP3 与 pro-IL-1β，第二信号由 K⁺ 外流、溶酶体破裂、ROS 等触发组装。\n\n【和生信分析的连接】转录层面最可靠的组合是「炎症小体组件 + 底物 + 成孔蛋白」：NLRP3、PYCARD（ASC）、CASP1、IL1B、IL18、GSDMD，外加 GSDME、CASP3。陷阱有三个：一是 IL1B 需要蛋白加工才成熟，mRNA 升高不代表分泌增加；二是 GSDMD 的活性取决于切割，全长蛋白表达量不等于活性；三是巨噬细胞是主要来源，组织整体信号会被浸润比例左右（见 method-23）。所以看到 NLRP3 升高，先判断是「实质细胞表达」还是「免疫细胞变多」。",
