    "body": "【主线】坏死性凋亡（necroptosis）是程序性的坏死，形态上是细胞肿胀、膜破裂、内容物外漏（因此有炎症性），分子上是 RIPK1 与 RIPK3 通过 RHIM 结构域互作形成坏死体（necrosome），RIPK3 再磷酸化 MLKL；磷酸化的 MLKL 寡聚并转位到膜上，直接打孔导致膜破裂。触发条件很特定：死亡受体（TNFR1、FAS、TRAILR）被激活，同时 caspase-8 活性被抑制（例如用 zVAD、病毒感染的 c-FLIP 模拟、或 cIAP 缺失）。\n\n【关键】这条通路是「备份」：凋亡受阻才启用，所以单独敲 RIPK3 在多数情况下表型轻微，只有联合 caspase 抑制才明显。近年补充的重要一环是 ZBP1：它识别 Z 型核酸（Z-RNA、Z-DNA），在病毒感染与某些炎症状态下直接激活 RIPK3，不经过 RIPK1。MLKL 是执行者也是最好的标志物（磷酸化 MLKL、寡聚 MLKL）。抑制剂谱系可以从上到下排：necrostatin-1（RIPK1）、GSK'872（RIPK3）、necrosulfonamide（人 MLKL）。\n\n【和生信分析的连接】转录特征不明显是这条通路最大的分析难点：RIPK1、RIPK3 的 mRNA 变化往往很小，MLKL 也不一定升高，因为激活靠磷酸化。所以「坏死性凋亡评分」在纯转录组里解释力有限，勉强可看的是 RIPK3、MLKL、ZBP1 与 TNF 通路的组合。实践上更可靠的做法是：如果数据里出现「凋亡通路被抑制（CFLAR、BIRC 高）+ 坏死样形态/炎症释放」的组合，才提示这条通路在起作用。任何仅凭 mRNA 的结论都应写成假设。",
