    "body": "【主线】巨自噬的流程：隔离膜（phagophore）成核需要 BECN1 与 PI3K 复合物（含 ATG14、VPS34），延伸需要 ATG12-ATG5-ATG16L1 结合系统与 LC3（MAP1LC3B）的脂化——LC3-I 被 ATG7 与 ATG3 加工并接上磷脂酰乙醇胺成为 LC3-II，锚定在自噬体膜上，所以 LC3-II/LC3-I 比值常被当作自噬体数量的指标。底物 p62（SQSTM1）与自噬体结合后被一起降解，因此 p62 升高可能意味着自噬流受阻而非自噬增强——这是最常被误读的地方。\n\n【关键】上游调控核心是 mTORC1：营养充足时 mTORC1 磷酸化 ULK1 抑制自噬，饥饿或雷帕霉素抑制 mTORC1 后 ULK1 激活、自噬启动；AMPK 则通过磷酸化 ULK1 与 TSC2 促进自噬。转录层面 TFEB/TFE3 入核启动自噬与溶酶体基因（见 death-09）。选择性自噬包括线粒体自噬（PINK1-Parkin、BNIP3、NIX）、内质网自噬、核糖体自噬等。所谓「自噬依赖性细胞死亡」在哺乳动物中证据有限，多数情况是自噬作为伴随现象或保护机制，判断必须靠通量实验（如加氯喹看是否加重死亡）。\n\n【和生信分析的连接】只有一个指标是不够的，标准组合是「LC3B + p62 + ATG 家族 + 溶酶体基因（CTSB、LAMP1、TFEB 靶基因）」。判读逻辑：LC3B 高 + p62 低 → 自噬流通畅；LC3B 高 + p62 高 → 自噬流受阻；两者都低 → 自噬不活跃。这个组合能避免「p62 高就说是自噬增强」的经典错误。另一个实用提醒：自噬相关基因在营养应激（如取材缺血时间过长）时会整体上调，这是技术伪影，需核对样本处理流程。",
