    "body": "【主线】合成致死的定义：基因 A 与 B 各自失活细胞仍能活，但同时失活就致死。经典例子是 BRCA1/2 与 PARP：BRCA 缺陷细胞无法做 HR，只能依赖 PARP1 参与的碱基切除修复与 alt-EJ 来处理单链断裂与复制叉损伤；抑制 PARP 后单链断裂累积成双链断裂，HR 又修不了，细胞就死。这就是 olaparib 等 PARP 抑制剂在 BRCA 突变肿瘤中有效的机制。\n\n【关键】PARP 抑制剂还有第二重机制叫「PARP 捕获」（trapping）：药物让 PARP1 卡在 DNA 上不脱落，形成毒性复合物，这比单纯抑制催化活性更致命。这也解释了不同药物之间的效力差异。耐药机制主要包括：HR 功能恢复（BRCA1/2 二次突变回复读框、RAD51 上调、53BP1 缺失使末端切除恢复）、药物外排、以及 PARP1 突变。适应证已从 BRCA 突变扩展到更广的「HR 缺陷（HRD）」表型，因此如何判定 HRD 就成了关键问题。\n\n【和生信分析的连接】纯计算判定 HRD 有三条路：一是基因组瘢痕（LOH、端粒等位基因失衡 TAI、大片段移位 LST）算 HRD score，这是目前最成熟的；二是转录签名（HR 模块低 + alt-EJ 模块高，见 radio-11）；三是突变层面（BRCA1/2、PALB2、RAD51C/D 的致病突变）。要提醒的是：HR 模块的 mRNA 低不等于功能缺陷，很多 HRD 肿瘤的 BRCA1 mRNA 正常（只是蛋白功能丧失或表观沉默）。所以转录组提示只能作为筛选，最终判定仍需基因组瘢痕或功能实验（RAD51 灶点）。",
