    "body": "【主线】溶酶体是酸性细胞器（V-ATPase 维持 pH），内含组织蛋白酶（CTSB、CTSD、CTSL）等水解酶，负责降解自噬产物与内吞物质。溶酶体膜通透（LMP）指膜完整性受损，让这些酶漏到胞质。触发因素包括：脂质过氧化产物、活性氧、某些药物（如羟基氯喹的衍生物、siramesine）、晶体物质、以及病原体。后果有三：水解酶造成广泛蛋白降解；cathepsin 可切 BID 或激活 caspase，把信号接到凋亡通路；以及 NLRP3 感知到泄漏后启动炎症。\n\n【关键】LMP 的判定标志比较特殊：galectin-3（LGALS3）在膜破损处聚集，是常用指标；吖啶橙染色由颗粒状转弥漫提示 pH 失衡。修复机制存在：TFEB/TFE3 入核促进溶酶体生物合成与自噬（这条与 mTORC1 抑制耦合，见 death-07），所以轻度损伤能修复，重度才致死。这也解释了为什么「溶酶体抑制剂」与「自噬抑制剂」在实验中常被混用却又效果不同——前者破坏功能，后者阻断降解，最终都导致溶酶体应激但路径不同。\n\n【和生信分析的连接】转录层面能看的主要是溶酶体生物合成程序：TFEB/TFE3 靶基因（CTSB、CTSD、LAMP1、MCOLN1、ATP6V1H）、以及 galectin 家族（LGALS3、LGALS8）。若这组基因整体上调，提示溶酶体应激与 TFEB 激活；若同时伴炎症小体基因上调，提示 LMP 已引发炎症。要强调的是：LMP 是细胞器层面的事件，转录组完全看不到，只能推断「溶酶体程序被调动」。做机制主张时这句限定必须写。",
