    "body": "【主线】免疫原性细胞死亡（ICD）指死亡过程伴随释放足够的免疫刺激信号，使树突状细胞成熟、抗原被呈递、T 细胞被激活，从而产生针对该抗原的免疫记忆。三个核心标志：钙网蛋白（CALR）从内质网外翻到细胞表面（「吃我」信号，促 DC 吞噬）、HMGB1 释放（经 TLR4 促 DC 成熟）、ATP 释放（经 P2RX7 招募与激活免疫细胞）。此外 I 型干扰素与核酸感受器（cGAS-STING）的激活是放大环节。\n\n【关键】并非所有死亡方式都免疫原性：凋亡通常被认为「安静」（凋亡细胞迅速被胞葬，不释放内容物）；坏死性凋亡、焦亡、以及部分化疗/放疗诱导的凋亡则偏「响」（因为膜破裂或主动分泌）。这也解释了治疗策略的一个方向：不只追求杀得多，还追求「死得对」——例如把凋亡转为焦亡（诱导 GSDME 表达，见 death-05），或联合 STING 激动剂。反过来，在正常组织损伤中，ICD 式的死亡会放大炎症，是放射性损伤迁延的机制之一（见 radio-19）。\n\n【和生信分析的连接】ICD 在转录层面没有单一签名，需要多组间接证据：DAMP 相关（HMGB1、CALR、ATP 释放相关基因如 PANX1）、I 型 IFN 签名（STAT1、IRF1、ISG15、CXCL10）、DC 活化（CD83、CCR7、HLA-DR）、以及死亡通路组合。实践上更常用的是「IFN 签名 + CD8 浸润 + 抗原呈递机器完整」三者同时成立。要提醒的是：CALR 外翻与 HMGB1 释放都是蛋白定位/释放事件，转录水平相关很弱，用 mRNA 论证 ICD 是常见的方法学过度解读。",
