    "summary": "每种死亡检测方法都只测一个侧面，组合才能定性。",
    "body": "【主线】Annexin V 结合外翻的磷脂酰丝氨酸（PS），配 PI 或 7-AAD 区分早晚期：Annexin V 单阳为早期凋亡，双阳为晚期/坏死。问题在于 PS 外翻并非凋亡专属——活化血小板、焦亡、铁死亡的细胞膜损伤都会暴露 PS，所以 Annexin V 阳性不能直接等同于凋亡。TUNEL 标记 DNA 断裂末端，任何产生 DNA 片段的死亡（凋亡、坏死、甚至严重 DNA 损伤修复中）都会阳性。caspase-3 活性检测（抗体测 cleaved caspase-3 或荧光底物）特异性较好，但若细胞走的是 caspase 非依赖通路就会假阴性。\n\n【关键】形态学仍是重要的锚：凋亡是细胞皱缩、染色质边集、凋亡小体；坏死性凋亡/焦亡是肿胀与膜破裂；铁死亡是线粒体皱缩、膜密度增高而核形态正常；自噬相关死亡可见大量自噬泡。分子标志方面：凋亡用 cleaved caspase-3、PARP 切割；焦亡用 GSDMD N 端、IL-1β 分泌；坏死性凋亡用 pMLKL；铁死亡用 4-HNE、MDA、C11-BODIPY；铜死亡用 DLAT 寡聚。最关键的验证手段是抑制剂挽救实验：zVAD 救凋亡、ferrostatin-1 救铁死亡、necrostatin-1 救坏死性凋亡、VX-765 救焦亡。\n\n【和生信分析的连接】转录组不能测死亡，只能测「死亡程序的表达倾向」。所以数据里说「铁死亡相关基因上调」是合适的，说「发生铁死亡」就越界了。如果课题必须给出死亡方式的证据，最经济的组合是：通路评分（分通路）+ 上游驱动因子（如 p53、IFN）+ 抑制剂挽救实验（体外）。另外注意采样时间：死亡是过程，早期与晚期样本的分子特征可能相反（早期抗凋亡代偿、晚期崩解），只取一个时间点很容易得出矛盾结论。",
