    "body": "【主线】流水线四步：蛋白酶体（免疫型含 PSMB8/9/10）把胞内蛋白切成 8-10 个氨基酸的肽段；TAP1/TAP2 二聚体把肽段从胞质泵进内质网；在内质网里肽段被修剪（ERAP1）并装载到 MHC-I 重链与 β2 微球蛋白（B2M）组成的复合物上（tapasin 参与稳定）；最后经高尔基体运到膜表面，供 CD8⁺ T 细胞的 TCR 识别。MHC-I 几乎在所有有核细胞上表达，是「自我介绍」的窗口。\n\n【关键】肿瘤逃逸最常用的手段就是关掉这个窗口，且方式很集中：B2M 失活突变（B2M 是 MHC-I 组装的必需轻链，坏了整条流水线停摆）、HLA-A/B/C 的杂合性缺失（LOH）或转录沉默、TAP1/2 下调、PSMB8 下调、以及 ERAP1 功能缺失。这类改变的临床意义相当直接：肿瘤对 CD8⁺ T 细胞与原发灶的检查点治疗抵抗，但对 NK 细胞反而更敏感（因为 NK 靠「缺失自我」识别，见 immune-08）。这也构成了「MHC-I 丢失 → 用 NK 或双特异抗体补位」的治疗思路。\n\n【和生信分析的连接】判断抗原呈递是否完整，要用一组基因而不是单个：HLA-A、HLA-B、HLA-C、B2M、TAP1、TAP2、PSMB8、PSMB9、TAPBP、ERAP1。要点有三：一是 HLA 基因多态性极高，通用比对流程会低估表达（多拷贝与多态导致 reads 分散），所以 HLA 定量要专门工具；二是 B2M 的突变常是截短突变，表达量下降可能不明显但功能全失，需要看突变数据；三是 IFN-γ 可上调整条流水线，所以「抗原呈递评分低」也可能只是「IFN 签名低」，两者要一起看。",
