    "summary": "免疫系统既防癌也「筛选」癌，筛出来的往往更难对付。",
    "body": "【主线】免疫编辑把免疫与肿瘤的关系分成三阶段。清除期（elimination）：固有免疫与适应性免疫协同杀死新生的转化细胞，NK、γδT、DC 与 CTL 都参与，此时肿瘤还没成形。平衡期（equilibrium）：残存细胞与免疫系统长期僵持，肿瘤不再长大但也没被清除，这个阶段可能持续多年，是「免疫压力下的静默演化期」。逃逸期（escape）：肿瘤获得逃避免疫的能力并快速生长，表现为临床可见的肿瘤。\n\n【关键】逃逸的手段可以归为四类：一是「藏起来」（MHC-I 下调、抗原丢失、形成物理屏障）；二是「关掉刹车」（PD-L1 上调、招募 Treg 与 MDSC、分泌 IL-10 与 TGF-β）；三是「改造环境」（缺氧、乳酸、色氨酸耗竭、腺苷积累）；四是「招募错的人」（把本应杀伤的髓系细胞改造成促瘤表型，见 immune-05）。理解这三阶段对治疗有直接含义：早期肿瘤免疫压力强，免疫治疗窗口更好；晚期肿瘤已经过筛选，逃逸机制冗余，单靶点常失败。\n\n【和生信分析的连接】免疫编辑留下的痕迹可以在基因组里找到：一是「免疫编辑负选择」——新抗原少、MHC 通路突变多的肿瘤往往经历过强免疫压力；二是克隆结构——逃逸克隆常在治疗或免疫压力后扩张（见 cancer-13）。转录层面可用「免疫浸润评分 + 抗原呈递评分 + 抑制性细胞评分」三者组合判断处于哪一阶段：三者都高且肿瘤增殖低，偏平衡期；浸润低而抑制性细胞高，偏逃逸期。提醒：这些判断都是横断面推断，真实分期需要纵向样本。",
    "keyPoints": [
      "三阶段：清除、平衡、逃逸，平衡期可持续多年",
      "逃逸手段四类：藏起来、关刹车、改造环境、招募错的人",
      "早期免疫压力强、治疗窗口好，晚期逃逸机制冗余",
      "免疫编辑的痕迹可从新抗原负荷与 MHC 通路突变反推"
    ],
    "testYourself": "为什么「免疫浸润高」既可能意味着预后好，也可能意味着肿瘤已进入逃逸期？",
