    "summary": "MDSC 是按「抑制功能」定义的，所以它的标志物天然不干净。",
    "body": "【主线】髓系来源抑制细胞（MDSC）是未成熟髓系细胞在病理状态下扩增、并被赋予强免疫抑制功能的群体。人分两类：PMN-MDSC（表型近中性粒细胞，CD11b⁺CD15⁺CD14⁻，低密度）与 M-MDSC（近单核细胞，CD11b⁺CD14⁺HLA-DR^low）。抑制机制主要有四：一是 Arg1（ARG1）耗竭微环境中的 L-精氨酸，使 T 细胞 CD3ζ 链丢失、增殖停滞；二是 iNOS（NOS2）产 NO 抑制 T 细胞；三是产 ROS；四是诱导 Treg 并下调 L-选择素影响 T 细胞归巢。\n\n【关键】标志物不干净是这条路线的根本困难：PMN-MDSC 与正常中性粒细胞在转录上高度相似，人源样本常需低密度梯度分离才能区分；小鼠的「经典」标志（Gr-1⁺CD11b⁺）实际标记了所有粒细胞与单核细胞。这就是为什么不同文献的 MDSC 比例差异巨大——多半不是生物学差异，而是分离与圈门方法差异。同理，转录组里几乎没有可靠的 MDSC 特异性标志，S100A8/A9、ARG1、ITGAM 都太宽泛。\n\n【和生信分析的连接】在纯计算里，更稳妥的表述是「髓系抑制程序」而不是「MDSC 比例」：用 ARG1、NOS2、S100A8、S100A9、S100A12、FCN1、VCAN、OLR1 组成模块评分，再与 CD8 浸润和 IFN 签名做负相关分析。要避免的坑：一是 S100A8/9 在鳞状上皮与角质细胞也高表达，非肝癌中会误判；二是中性粒细胞确实会形成 NETs（见 tme-10），其基因特征与 MDSC 部分重叠；三是外周血与肿瘤内的 MDSC 不是同一群，不能互相代替。",
