    "summary": "NK 的逻辑是缺什么就杀，MHC-I 丢失的肿瘤正中枪口。",
    "body": "【主线】NK 细胞属固有免疫，不需要抗原预致敏就能杀伤。它的决策靠整合两类信号：激活信号（NKG2D/KLRK1 识别 MICA/MICB、ULBP1-6 等应激配体；NCR1/NKp46；CD16/FCGR3A 介导 ADCC；NKp30、NKp44）与抑制信号（KIR 家族与 CD94-NKG2A 识别 MHC-I）。当抑制信号缺失（MHC-I 下调，即「缺失自我」）而激活信号存在时，NK 被许可杀伤。\n\n【关键】这条逻辑与 T 细胞互补：肿瘤为了躲 T 细胞下调 MHC-I，结果暴露给 NK；反过来，肿瘤为了躲 NK 保留 MHC-I，又容易被 T 细胞识别。这种「两难」是 NK 与 T 细胞联合治疗的理论基础。NK 的临床应用有三条路：一是 NK 细胞过继输注（同种异体、脐带血或 iPSC 来源）；二是双特异/三特异抗体（一端连 CD16 或 NKp46，一端连肿瘤抗原，绕过 MHC）；三是检查点（NKG2A 抗体阻断抑制信号）。难点在于 NK 在体内的持久性差、在肿瘤微环境中功能被 TGF-β 与缺氧抑制。\n\n【和生信分析的连接】NK 评分用 KLRF1、KLRD1、NKG7、GNLY、PRF1、NCR1、KIR2DL3、KIR3DL1 等，但要小心：NKG7 与 GNLY 在 CTL 中也高表达，单独用会把 CD8 T 细胞算成 NK。更细的分辨要靠组合（NK 缺 CD3D/CD3E，T 细胞有）。另一个实用点：MHC-I 评分（HLA-A/B/C、B2M）与 NK 激活配体评分（MICA/MICB、ULBP1-3）的比值，比单看任一侧更能反映「NK 是否该被激活」。注意 MICA/MICB 多态性高，通用定量同样不可靠。",
