    "summary": "这条通路把「DNA 放错位置」翻译成「启动 I 型干扰素」。",
    "body": "【主线】cGAS（MB21D1）是胞质 DNA 感受器，结合双链 DNA 后被激活，用 ATP 与 GTP 合成环二核苷酸 cGAMP；cGAMP 结合内质网上的 STING（STING1/TMEM173），使 STING 寡聚并从内质网经高尔基体转位，招募 TBK1 并磷酸化 IRF3，IRF3 二聚入核启动 IFNB1 与干扰素刺激基因（ISG）；STING 同时激活 IKK-NF-κB 促炎分支。这条通路本来用于抗病毒与抗胞内菌，在肿瘤里则成为「放疗/化疗如何激活免疫」的关键环节（见 radio-16）。\n\n【关键】几个反复考的点：一是 cGAS 的激活不依赖序列，只依赖 DNA 长度与结构，所以任何来源的胞质 DNA（微核、线粒体 DNA 泄漏、病毒）都能触发；二是 STING 的转位是必需步骤，阻断高尔基转运（如某些药物）就能抑制信号；三是肿瘤常通过表观沉默 STING 或下游 ISG 来逃逸，这是「冷肿瘤」的机制之一；四是 STING 激动剂（如 cGAMP 类似物、DMXAA 仅对小鼠有效）在临床上的全身给药毒性限制了应用，所以多采用瘤内注射。\n\n【和生信分析的连接】判断这条通路是否活跃，看 ISG 签名（STAT1、IRF1、ISG15、MX1、OAS1、IFIT1/3、CXCL10）与 STING/IRF3 本身。这里有个经典陷阱：ISG 高既可能是「STING 激活」，也可能是「IFN-γ 信号（JAK-STAT1）」或「病毒感染」，三者共用下游。要区分，看上游：CGAS、STING1、TBK1 的表达与突变状态，以及是否有 IFN-γ 特征（CXCL9、GBP1、IDO1 更偏 IFN-γ）。另外 STING 在肝癌中常被甲基化沉默，所以「表达低」本身就是一个有意义的发现。",
