    "summary": "有 TLS 的肿瘤对免疫治疗更敏感，因为它就地完成抗原呈递。",
    "body": "【主线】三级淋巴结构（TLS）是在慢性炎症部位异位形成的淋巴样组织，结构上包含 T 细胞区（CD3⁺、CD4⁺）、B 细胞滤泡（CD20⁺、CD21⁺ 滤泡树突细胞网络）、生发中心（BCL6⁺、AICDA⁺）、以及高内皮微静脉（PNAd⁺、MECA-79）。形成的关键趋化因子是 CXCL13（由 LAMP3⁺ 成熟 DC、T 细胞与基质细胞分泌）招募 CXCR5⁺ B 细胞，配合 CCL19/CCL21-CCR7 组织 T 细胞区。\n\n【关键】TLS 的临床意义在多个瘤种中被反复验证：成熟 TLS（含生发中心）与更好的免疫治疗响应和更长生存相关。原因是它提供了「就地免疫应答」的场所：DC 在此呈递抗原、B 细胞在此类别转换产生抗体、T 细胞在此被激活并进入肿瘤。肝癌中也观察到 TLS 与预后相关，且常出现在纤维化区域边缘。治疗启示是「诱导 TLS 形成」可能比单纯增加 T 细胞浸润更有效，相关策略包括抗血管正常化（见 tme-07）、CXCL13 诱导、以及 LIGHT（TNFSF14）等淋巴组织诱导因子。\n\n【和生信分析的连接】纯计算无法直接看到结构，只能用「淋巴组织形成程序」间接推断：CXCL13、CCL19、CCL21、LAMP3、CR2、MS4A1、BCL6、AICDA、PNAd 相关（GLYCAM1、SELP）。建议做一个 TLS 评分并明确写成「TLS 相关转录程序」，不要写成「存在 TLS」——后者需要病理或空间转录组证据。另一个常见误判：CXCL13 在 CD8 耗竭 T 细胞中也高表达（见 immune-03），所以单独用 CXCL13 会把「耗竭」误判为「TLS」。",
