    "summary": "冷肿瘤不是「没有免疫」，而是「免疫进不去或被挡住」。",
    "body": "【主线】先分清两种「冷」：免疫荒漠（免疫细胞极少，多为低突变负荷、无抗原）与免疫排斥（免疫细胞被挡在间质边界，进不到瘤巢）。前者的问题是「没有兵」，后者的问题是「兵在门外」。这个区分决定了策略：荒漠型要做的是制造抗原与炎症（溶瘤病毒、放疗、表观药物去沉默内源抗原、STING/TLR 激动剂）；排斥型要做的是拆墙（抗 TGF-β、降解基质、抗血管正常化、FAP 靶向）。\n\n【关键】五类常用策略是：一是放疗/化疗诱导 ICD（见 death-11）；二是溶瘤病毒与瘤内免疫激动剂（把「冷」局部变「热」）；三是抗血管正常化改善 T 细胞灌注（见 tme-07）；四是表观遗传药物（DNMT 与 HDAC 抑制剂）去沉默内源逆转录病毒序列与抗原呈递基因；五是改造髓系（CSF1R、CD47、TLR 激动剂）。失败原因往往一致：只处理了一个环节。例如只加 PD-1 抗体但肿瘤没有 T 细胞，等于给空房间装门锁；只做抗 TGF-β 但抗原呈递已丢失，T 细胞进来了也认不出目标。\n\n【和生信分析的连接】判断「冷」的类型要看空间与组成两层：组成上比较 CD8 浸润（CD8A、GZMB）与总免疫（PTPRC）；空间上若无空间数据，可用「间质/基质评分高而瘤巢免疫评分低」的组合间接提示排斥。另外必须检查抗原呈递（见 immune-01）与 IFN 通路是否完整（JAK1/2 突变会导致对 IFN-γ 无反应，是原发性耐药机制）。做联合治疗预测时，建议按「缺哪一环」分类报告，而不是给一个笼统的「免疫冷热」标签。",
