    "summary": "CAR-T 在血液瘤是明星，到实体瘤要面对四道墙。",
    "body": "【主线】第一道墙是抗原异质性：实体瘤缺乏像 CD19 那样「全瘤均一、且非必需」的靶点，单一抗原的 CAR-T 会选择性清除高表达克隆，低表达克隆逃逸（见 cancer-13）。第二道墙是物理屏障：致密基质、异常血管、高间质压使 CAR-T 难以浸润（见 tme-08）。第三道墙是微环境抑制：TGF-β、IL-10、腺苷、乳酸、缺氧、Treg 与 MDSC 共同压制 CAR-T 功能（见 tme-09）。第四道墙是 T 细胞自身：在持续抗原刺激下快速耗竭（见 immune-03），持久性差。\n\n【关键】应对思路也很具体：抗原侧用双靶点或「与门」逻辑 CAR（需两个抗原同时存在才激活，降低脱靶）；浸润侧用局部给药、表达趋化因子受体（如 CXCR3、CCR2b）或改造基质降解能力；微环境侧做「装甲 CAR」（分泌 IL-12、IL-18，或表达 TGF-β 显性负性受体）；T 细胞侧用 CRISPR 敲除抑制性受体或内源 TCR，或改用「通用型」与记忆表型富集的制备工艺。肝癌的候选靶点包括 GPC3、AFP（需 MHC 呈递）、 Claudin 等，共同风险是 on-target off-tumor（正常肝细胞也表达）。\n\n【和生信分析的连接】纯计算能为 CAR-T 做的分析主要有三块：一是靶抗原的表达特异性（肿瘤 vs 正常组织，尤其肝、心、肺等关键器官，必须查 GTEx 类正常组织数据）；二是抗原异质性（单细胞里靶基因表达的分布与阳性比例，而不是平均值）；三是微环境抑制评分（TGFB1、CD274、ENTPD1、NT5E、ADCYAP1R1 等）。要提醒的是：靶点选择不能只看表达量，还要看是否可被抗体接近（膜表面 vs 分泌型）与是否在关键器官表达。",
