    "summary": "CAF 至少三类，功能从筑墙到送粮再到拦免疫各不相同。",
    "body": "【主线】单细胞研究把肿瘤相关成纤维细胞（CAF）大致分成三类：myCAF（肌成纤维样，ACTA2、TAGLN、MYH11、COL1A1 高，收缩性强，形成致密基质）；iCAF（炎症型，IL6、CXCL12、PDGFRA、HAS1 高，分泌细胞因子与炎症介质）；apCAF（抗原呈递型，表达 MHC-II 与 CD74，能向 T 细胞呈递抗原但缺乏共刺激，可能导致耐受）。此外还有以 FAP、POSTN、MMP11 为标志的亚群，以及近年提出的「血管型 CAF」与「外泌体型 CAF」。\n\n【关键】功能不是「都促癌」：myCAF 通过致密基质形成物理屏障、降低药物渗透；iCAF 分泌 CXCL12 排斥 T 细胞、并支持肿瘤细胞存活；apCAF 可能诱导 T 细胞耐受。但也有报道某些 CAF 亚群具有抑癌作用（如限制肿瘤侵袭的「基质屏障」效应），所以「清除所有 CAF」的策略在动物实验中常出现反效果（炎症加重、肿瘤侵袭增强）。这解释了为什么 FAP 靶向治疗需要极精细的亚群选择性。\n\n【和生信分析的连接】CAF 分型分析的三个要点：一是 CAF 与正常成纤维细胞、平滑肌细胞、周细胞的区分——ACTA2 与 TAGLN 在这几类里都表达，必须组合（如 PDGFRA、DCN、LUM 偏 CAF/成纤维，RGS5、NOTCH3 偏周细胞）；二是解离会显著改变 CAF 的转录状态（应激基因 JUN/FOS 飙升）；三是 bulk 数据里「基质评分高」往往同时意味着「肿瘤细胞比例低」，会系统性影响所有其他评分（见 method-23）。建议报 CAF 亚型比例而非单一「CAF 评分」。",
