    "summary": "HSC 是肝纤维化主角，活化时同时失去身份与刹车。",
    "body": "【主线】静止态 HSC 位于窦周间隙（Disse 间隙），主要功能是储存维生素 A 脂滴，标志基因包括 LRAT、GFAP、DES、NGFR、HHIP。活化分两步：启动（initiation）由旁分泌信号驱动——损伤肝细胞与 Kupffer 细胞释放 TGF-β1、PDGF、IL-6、ROS，使 HSC 失去脂滴、上调 PDGFRB 与 ACTA2；持续（perpetuation）由自分泌与基质硬度维持——活化的 HSC 自己分泌 TGF-β1 与 TIMP1，基质变硬又通过整合素与 YAP 进一步强化活化（见 tme-05）。\n\n【关键】活化后的 HSC 做四件事：收缩（使肝窦变窄、门静脉阻力升高）、增殖、分泌基质（COL1A1、COL3A1、FN1）、以及分泌 TIMP1 抑制 MMP 介导的基质降解。因此纤维化的「不可逆」不是因为基质合成太多，而是因为降解被抑制 + 交联（LOX 家族）让基质难以被酶切。逆转的可能路径是：去除病因（如抗病毒）、诱导 HSC 凋亡或衰老、以及促进 MMP 活性。肝癌中的 CAF 有很大一部分来自活化 HSC，这是肝癌与纤维化研究共享的细胞学基础。\n\n【和生信分析的连接】识别 HSC 的关键是「LRAT/GFAP 下降 + ACTA2/COL1A1 上升」的双向变化，单看 ACTA2 会把血管平滑肌误算进去。单细胞里 HSC 与 portal fibroblast、血管周细胞容易混，可加看 HHIP、RELN、DCN。另外注意：肝内 HSC 在正常肝中占比很低，bulk 数据里的「HSC 活化签名」很可能主要反映纤维化程度而非 HSC 数量，两者在因果上不同。做药物靶点筛选时，PDGFRB、TGFBR1、LOXL2、FAP 都是被反复验证的候选。",
