    "body": "【主线】三条主要机制。第一是色氨酸耗竭：肿瘤与髓系细胞高表达 IDO1/TDO2，把色氨酸分解成犬尿氨酸，T 细胞因缺乏色氨酸而停滞，同时犬尿氨酸通过 AhR 促进 Treg。第二是腺苷积累：CD39（ENTPD1）把 ATP 转成 AMP，CD73（NT5E）再转成腺苷，腺苷通过 A2A 受体（ADORA2A）升高 cAMP，抑制 TCR 信号与细胞毒功能。第三是乳酸：肿瘤糖酵解产生大量乳酸（见 cancer-06），经 MCT1/SLC16A1 进入 T 细胞后抑制其增殖与 IFN-γ 分泌，并推动 TAM 向促瘤表型极化。\n\n【关键】这三条的共同点是「可被药物干预」：IDO1 抑制剂、A2A 受体拮抗剂、MCT1 抑制剂都做过临床试验，单药效果普遍有限——原因很可能是代谢冗余：堵一条，肿瘤换另一条。另一个重要概念是「营养竞争」不只发生在肿瘤与 T 细胞之间，也发生在肿瘤与正常实质细胞之间（例如肝癌抢夺葡萄糖影响肝功能）。此外，氨基酸剥夺会触发整合应激反应（GCN2、ATF4），这本身也是一条可测的签名。\n\n【和生信分析的连接】这三条都能在转录层面看到：IDO1、KYNU、TDO2（色氨酸轴）；ENTPD1、NT5E、ADORA2A、ADORA2B（腺苷轴）；LDHA、SLC16A1、SLC2A1、HK2（乳酸轴）。要注意三点：一是 IDO1 是 IFN-γ 的强诱导基因，所以「IDO1 高」也可能只是「T 细胞活跃」，方向要靠 CD8 与 IFN 签名一起判断；二是 NT5E 在基质与内皮也表达，不全是免疫细胞；三是这些基因的表达量与代谢通量不必然一致，纯转录只能提示「通路被布置」。",
