    "body": "【主线】中性粒细胞被激活后可发生「NETosis」：染色质解聚、组蛋白瓜氨酸化（由 PAD4/PADI4 催化）、颗粒蛋白（MPO、ELANE、NE）与 DNA 一起被挤到胞外，形成网状结构。生理功能是捕获并杀伤病原体。触发因素包括 ROS、炎症因子、活化血小板、以及肿瘤来源因子。有两种形式：自杀性 NETosis（细胞破裂）与活性氧依赖的「vital NETosis」（细胞仍存活）。\n\n【关键】在肿瘤里 NETs 的作用是双面的：一方面捕捉循环肿瘤细胞、促进其定植（转移的「土壤」作用）、并包裹微转移灶阻挡 CTL 与 NK；另一方面过度 NETs 会促进血栓（与 Trousseau 综合征相关）、损伤内皮、加重炎症。在肝脏，NETs 参与缺血再灌注损伤、酒精性肝炎与脓毒症肝损伤。靶向策略包括 DNase I（降解 NET DNA）、PAD4 抑制剂、以及 NE/MPO 抑制剂，但都面临「影响正常免疫防御」的风险。\n\n【和生信分析的连接】NETs 的转录标志很难干净：常用 PADI4、ELANE、MPO、CTSG、S100A8/9、H3Cit（蛋白修饰，转录看不到）、以及 cfDNA 水平（需血浆）。三个提醒：一是这些基因与未成熟粒细胞、MDSC 高度重叠（见 immune-06），所以「NET 评分高」更可能反映「粒细胞浸润多」；二是 NETs 的核心是蛋白修饰与胞外 DNA，转录组无法直接看到；三是血浆 cfDNA 与 MPO-DNA 复合物是更直接的指标，但需要配套样本。所以纯计算里宜报「中性粒细胞活化/粒细胞浸润」，慎用「NETs 形成」这一说法。",
