    "id": "method-16",
    "domain": "method",
    "domainName": "生信方法论",
    "title": "弱工具偏倚：F 统计量为什么是 MR 的第一道体检",
    "level": "进阶",
    "tags": [
      "弱工具",
      "F统计量",
      "工具变量",
      "MR"
    ],
    "summary": "工具太弱，MR 的结果会被拉回「普通观察性研究」的答案。",
    "body": "【主线】孟德尔随机化用遗传变异作为工具变量估计暴露对结局的因果效应。工具必须与暴露强相关（相关性假设），否则称为弱工具。弱工具带来两个后果：一是估计精度差（标准误大）；二是更隐蔽的——在两样本 MR 中，弱工具会把估计「拉向」暴露与结局的混杂关联（方向取决于样本重叠），也就是说你以为在做因果推断，其实在做带噪声的相关分析。\n\n【关键】常用体检指标是 F 统计量，经验上单个工具 F 大于 10 被认为足够强（这是一条经验阈值，不是定理）。近似算法：F ≈ (R²/(1−R²)) × (n−k−1)/k，或用 β²/se² 的近似。此外还要看：一是工具数量与解释方差（R²）是否太小；二是是否存在「赢家诅咒」（在全基因组显著阈值下挑出的 SNP，其效应量被高估，独立样本可缓解）；三是工具是否集中在少数基因区域（如 HLA 区、ApoE 区），这类工具往往有多效性。\n\n【和生信分析的连接】做 MR 时的标准报告项：每个 SNP 的 β、se、F；总体 F 或 R²；工具数量；以及是否做了 clumping 去除连锁不平衡（否则同一信号的多个 SNP 会被当成多个独立工具，人为提高精度）。另一个高频错误是暴露与结局用了不同的人群 ancestry（如暴露用欧洲、结局用东亚），这会破坏工具与暴露的对应关系。若 F 偏低，补救办法是改用更宽松的阈值并做敏感性分析，或换用更大样本的 GWAS——而不是直接报告结果。",
    "keyPoints": [
      "弱工具会把 MR 估计拉向混杂的观察性关联",
      "F 统计量经验阈值约 10，可用 β²/se² 近似",
      "赢家诅咒会高估工具效应，独立样本可缓解",
      "暴露与结局的 ancestry 必须匹配，clumping 不可省"
    ],
    "testYourself": "为什么「工具变量 F 值很低但结果显著」反而更值得怀疑，而不是更值得相信？",
    "links": [
      "method-08",
      "method-17",
      "method-18",
      "method-09"
    ]
