    "domain": "method",
    "domainName": "生信方法论",
    "title": "空间转录组与 Moran's I：把「位置」变成可检验的变量",
    "level": "前沿",
    "tags": [
      "空间转录组",
      "Moran's I",
      "空间自相关",
      "SVG"
    ],
    "summary": "空间数据的核心不是表达多少，而是表达是否与位置相关。",
    "body": "【主线】空间转录组（如 Visium、Slide-seq、Xenium、CosMx）测的是带坐标的表达。分析的第一步通常是找空间可变基因（SVG）：表达在空间上呈现非随机分布的基因。常用统计量是 Moran's I，它衡量相邻位置的取值相似度：I 接近 1 表示强正自相关（近处相似），接近 0 表示随机，负值表示「近处反而不同」（如棋盘状模式）。类似指标还有 Geary's C 与基于图的方法（如 SpatialDE、SPARK-X）。\n\n【关键】三个技术要点：一是「邻居」怎么定义——网格、KNN、半径邻域会给出不同结果，需在方法中写明；二是分辨率限制——Visium 每个 spot 含多个细胞，测到的是混合信号，需要反卷积（见 method-23）或多细胞模型；三是切片间的对齐与坐标系差异，多样本比较时要先做标准化与配准。此外还有「空间域的识别」（如 BayesSpace、GraphST），本质是在表达相似性上再加空间平滑先验，因此会人为制造「区域感」——判断时要看不用空间先验时是否也能分出相似结构。\n\n【和生信分析的连接】对 RILD 这类「损伤有空间分布」的课题，空间数据是天然的落点：可以把「距中央静脉的距离」「距照射野边缘的距离」作为协变量，检验分区基因与损伤基因是否呈梯度。实操建议：一是先做质控（spot 覆盖度、线粒体比例），二是 SVG 分析要用多个方法交叉验证，三是做「空间梯度」时用滑动窗口或距离回归，而不是简单分组。最后提醒：切片是一个二维截面，三维结构（如肝小叶的立体走向）不能直接从一张切片推断。",
    "keyPoints": [
      "空间数据的核心问题是「表达是否与位置相关」",
      "Moran's I 衡量空间自相关，正值表示近处相似",
      "Visium 的 spot 是多细胞混合，需反卷积",
      "带空间先验的聚类会人为制造区域感，需与无先验结果对照"
    ],
    "testYourself": "Moran's I 很高的基因一定是「有生物学意义的空间结构」吗？还可能是什么？",
