    "summary": "反卷积给的是「与参考矩阵最吻合的解」，不是真实细胞计数。",
    "body": "【主线】反卷积的目标是从 bulk 表达里估计各细胞类型的比例。主流方法（CIBERSORTx、quanTIseq、EPIC、xCell）都需要一个参考矩阵——即各细胞类型的特征表达谱，来源多为排序纯化的细胞或单细胞数据聚合。算法本质是带约束的线性回归（非负、和为一），求「哪些细胞类型的加权组合最能解释观测表达」。\n\n【关键】四个根本局限：一是参考依赖——参考矩阵里没有的细胞类型，其信号会被强行分摊给已有类型（所以「未知细胞」会被算成最相似的已知类型）；二是共线性——表型相近的细胞（如 CD4 记忆与 naive、M1 与 M2 巨噬）特征高度相似，比例无法稳定区分，估计值对噪声极敏感；三是绝对量不可得——多数方法给出的是相对比例，某类型比例上升可能只是别的类型下降；四是组织特异性——用血液参考矩阵去解肝脏组织，结果不可信。\n\n【和生信分析的连接】使用规范：一是明确写出参考矩阵来源与算法版本；二是报告时用「估计比例」而非「细胞数量」；三是做敏感性分析（换一个算法看结论是否一致），若两个算法结论相反，就不要下强结论；四是不要把反卷积比例当作连续变量直接做相关分析而不考虑其误差（误差很大的变量做回归会产生衰减偏倚）。对本课题尤其重要：肝脏里的 Kupffer、单核来源巨噬、LSEC 在参考矩阵里常被合并或缺失，所以「巨噬细胞比例升高」这句话的可解释性很有限（见 immune-05）。若样本还含大量坏死区，比例估计会进一步失真。",
    "keyPoints": [
      "反卷积 = 用参考矩阵做带约束的线性回归，求解「最吻合的组合」",
      "参考矩阵缺失的细胞类型会被强行分摊给相似类型",
      "表型相近的细胞共线，比例无法稳定区分",
      "多给相对比例，不给绝对数量；换算法做敏感性分析"
    ],
    "testYourself": "CIBERSORTx 说「M2 巨噬细胞比例升高」，你能得出什么结论、不能得出什么结论？",
