    "id": "method-27",
    "domain": "method",
    "domainName": "生信方法论",
    "title": "基因集打分四兄弟：ssGSEA、GSVA、AUCell、AddModuleScore 的差别",
    "level": "进阶",
    "tags": [
      "ssGSEA",
      "GSVA",
      "AUCell",
      "模块评分"
    ],
    "summary": "四种方法算的不是同一件事，所以分数不能跨数据集比较。",
    "body": "【主线】四者的思路不同。ssGSEA：对每个样本，把基因按表达排序，用基因集成员的秩次做加权和经验分布，得到富集分数（本质是把 GSEA 的算法用到单样本上）。GSVA：用核密度估计把表达转成「每个样本每个基因的相对秩」，再做类似 Kolmogorov-Smirnov 的统计，输出可正可负的富集分数，适合做样本间的通路差异。AUCell：基于排名，计算基因集成员在单个细胞排名中的曲线下面积，特别适合单细胞，能给出「细胞是否表达该程序」的二元判定。AddModuleScore（Seurat）：把目标基因集的平均表达减去随机对照基因集的平均表达，简单直观但受表达量与批次影响最大。\n\n【关键】选择逻辑：bulk 数据做通路活性用 ssGSEA/GSVA（后者在同一队列内比较更敏感）；单细胞数据用 AUCell（阈值判定）或 AddModuleScore（快速探索）。共同问题是「分数没有绝对单位」——不同数据集、不同平台的分数不可比，必须在自己数据内做标准化（如 z-score）后再比较。另外基因集大小与内部相关性都会影响分数分布，长基因集分数方差更小。\n\n【和生信分析的连接】三条铁律：一是同一篇文章里所有样本必须用同一方法、同一基因集、同一参数算；二是跨数据集比较只能比较「方向的排序」，不能比较绝对值；三是做与预后的关联时，先检查该分数是否与肿瘤纯度、细胞组成强相关（见 method-23），否则你可能只是在测纯度。若要做「某通路在两个数据集都升高」的稳健结论，建议在两个数据集内分别做 z-score，再看升高方向是否一致。",
    "keyPoints": [
      "ssGSEA/GSVA 面向 bulk，AUCell 面向单细胞，AddModuleScore 最粗略",
      "分数没有绝对单位，跨数据集不可比",
      "基因集大小与内部相关性影响分数分布",
      "分数常与纯度、细胞组成强相关，必须先检查"
    ],
    "testYourself": "两个数据集里「铁死亡评分」分别是 0.42 与 0.61，能说后者铁死亡更强吗？为什么？",
