    "summary": "NF-κB 平时被锁在胞质，钥匙一拧就进核启动上百个基因。",
    "body": "【主线】经典通路：静息时 NF-κB 二聚体（多为 RelA/p50）被抑制蛋白 IκBα 结合，锁在胞质。刺激（TNF、IL-1、LPS、ROS）激活 IKK 复合物（IKKα/IKKβ/NEMO），IKKβ 磷酸化 IκBα 的两个丝氨酸，磷酸化的 IκBα 被 βTrCP 识别并泛素化降解，NF-κB 释放入核，启动 TNFAIP3（A20）、NFKBIA（IκBα）、CXCL8、BIRC2/3、IL6 等。注意 NFKBIA 本身是靶基因，所以它升高意味着「通路刚被激活过」——这是典型的负反馈。非经典通路则靠 NIK 积累激活 IKKα，把 p100 加工成 p52，与 RelB 组成二聚体，主要参与淋巴器官发育与 B 细胞存活。\n\n【关键】NF-κB 在肝脏里是双向的：短期激活促炎、促存活，帮助肝细胞抵抗凋亡（因此在急性损伤中有保护作用）；长期激活则驱动慢性炎症、纤维化与肝癌（见 radio-19）。这也是为什么「抑制 NF-κB 治肝病」的想法在动物实验里结果不一致——抑制时机与细胞类型决定了利大于弊还是相反。另一个关键点：NF-κB 与 p53 常互为抑制，两者的平衡决定「损伤细胞是修复还是凋亡」。\n\n【和生信分析的连接】评价 NF-κB 活性要用靶基因集（NFKBIA、TNFAIP3、BIRC3、CXCL8、CCL20、IL6、NFKB2），不要用 RELA 的 mRNA。三个陷阱：一是靶基因含大量趋化因子，会被免疫细胞浸润「污染」（见 method-23）；二是 NFKBIA 与 TNFAIP3 是负反馈基因，高表达既可能表示「刚激活」也可能表示「持续抑制失败」；三是 NF-κB 与 IFN、STAT 通路共享部分靶基因（如 CXCL9/10），方向要靠上游区分。",
