      "AKT 三大分支：激活 mTORC1、抑制 FOXO、促葡萄糖摄取",
      "PTEN 是主要刹车，mTOR 抑制剂会因负反馈解除而效果有限",
      "通路活性靠磷酸化，mRNA 只能间接推测"
