    "summary": "一条三级激酶链，把膜上的信号一路传到核内即刻早期基因。",
    "body": "【主线】RTK 激活 → GRB2-SOS 把 RAS 上的 GDP 换成 GTP → RAF（ARAF/BRAF/CRAF）被激活 → MEK1/2 双特异性激酶磷酸化 ERK1/2 的 Thr 与 Tyr → ERK 入核磷酸化 ELK1、c-FOS、c-MYC 等，启动增殖程序。ERK 也磷酸化胞质底物（如 RSK、MNK），并磷酸化 SOS、RAF 产生负反馈。刹车系统包括 DUSP 家族（去磷酸化 ERK）、SPRY 家族（抑制 RTK 信号）、以及 RASA1（RAS GTPase 激活蛋白）。\n\n【关键】这条通路是肿瘤中最常被激活的之一（RAS 突变、BRAF V600E、RTK 扩增、NF1 缺失）。临床教训也很典型：BRAF 抑制剂在黑色素瘤中效果显著，但在结肠癌中效果差，原因是结肠癌细胞通过 EGFR 快速「绕过」BRAF 抑制产生反馈性 RAS 激活——这说明「同一个突变在不同组织里网络结构不同」。另一个重要分支是 p38 与 JNK（应激活化），它们更多参与炎症与凋亡，方向常与 ERK 相反。\n\n【和生信分析的连接】ERK 活性同样主要看磷酸化，转录层面可看靶基因（FOS、JUN、EGR1、MYC、DUSP6、SPRY2、ETV4/5）。这里有个实用技巧：DUSP6 与 SPRY2 是 ERK 的负反馈靶基因，它们的表达是 ERK 活性的良好替代指标（尤其在 BRAF 突变肿瘤里）。但要区分「ERK 靶基因高」与「RAS 突变」——前者也见于 RTK 激活。在肝癌里 RAS/BRAF 突变频率不高，ERK 通路激活更多来自上游（EGFR、FGFR、MET），所以看到 ERK 签名高不要直接推断 RAS 突变。",
