    "summary": "不用级联放大，JAK 磷酸化 STAT 后直接进核转录。",
    "body": "【主线】细胞因子（IL-6 家族、IFN、GM-CSF 等）结合受体后使受体二聚化，激活与之结合的 JAK（JAK1/2/3、TYK2）。JAK 磷酸化受体胞内段的酪氨酸，形成停靠位点招募 STAT 的 SH2 结构域；JAK 再磷酸化 STAT 的酪氨酸，STAT 二聚化入核启动靶基因。不同组合决定特异性：IL-6 家族主要走 JAK1-JAK2-STAT3（需 gp130），IFN-α/β 走 JAK1-TYK2-STAT1/STAT2，IFN-γ 走 JAK1-JAK2-STAT1。\n\n【关键】负反馈有三层：SOCS 家族（SOCS1/3 结合 JAK 或受体并促降解，本身是 STAT 靶基因）、PIAS 家族（抑制 STAT 与 DNA 结合）、以及磷酸酶 SHP1/SHP2（PTPN6/PTPN11，SHP2 同时也正向调节 RAS）。这种「靶基因即刹车」的结构意味着：SOCS3 高表达既说明通路被激活过，也可能是通路被压制的原因——判读必须结合时间点。STAT3 在肝脏里极其重要：它是再生启动的关键（见 regen-17），也是肝癌中促增殖、抗凋亡、促免疫抑制的核心节点，且 STAT3 在肿瘤细胞与免疫细胞中的作用方向不同（在髓系细胞里抑制 STAT3 反而削弱抗肿瘤免疫）。\n\n【和生信分析的连接】STAT3 靶基因集可用 SOCS3、FGA、FGB、HP、SERPINA3、BCL2L1、MCL1、VEGFA、IL6、MMP9，但注意这些都是「炎症 + 急性期 + 存活」的混合，容易被急性期反应主导（见 regen-08）。STAT1 靶基因则与 IFN 签名重叠（见 signaling-11）。判定时要分开：STAT1 高偏「免疫激活」，STAT3 高偏「炎症与存活」。另一个技术点：JAK2 V617F 这类激活突变在骨髓增殖性肿瘤中常见，在肝癌中罕见，别混用。",
