    "body": "【主线】没有 SHH 时，PTCH1 位于初级纤毛并抑制 SMO；GLI2/3 被 SUFU 与激酶（PKA、GSK3β、CK1）磷酸化，部分降解成阻遏型（GLI3R）入核抑制靶基因。SHH 结合 PTCH1 后，PTCH1 离开纤毛、SMO 进入纤毛并激活，SUFU 被解除，GLI2 转为激活型（GLI2A）入核启动 GLI1、PTCH1、HHIP、CCND1、MYC。注意 GLI1 是靶基因，也是正反馈放大器。\n\n【关键】在肝脏里，Hh 通路主要作用于两类细胞：活化的肝星状细胞（促纤维化，见 tme-02）与祖细胞/胆管反应（促修复）。但在肝细胞癌中，Hh 的作用有争议——多数研究认为它是旁分泌的（肿瘤细胞分泌配体，作用于基质），而不是肿瘤细胞自身的自分泌驱动，所以 SMO 抑制剂（如 vismodegib）在 HCC 中疗效不佳。这是一个很好的例子：通路「被激活」与「是驱动事件」是两件事，前者可能是结果而非原因。\n\n【和生信分析的连接】Hh 评分用 GLI1、PTCH1、HHIP、GLI2、CCND1、MYC，但 GLI1 与 PTCH1 是最特异的。三个陷阱：一是 SHH 表达可以来自基质，检测整块组织时无法判断来源；二是 GLI1 在非经典激活（不依赖 SMO）时也升高，所以「SMO 抑制剂无效」不代表通路没激活；三是肝脏中 Hh 签名与纤维化签名高度重叠，很难分开。若要做「Hh 是否是驱动」的判断，最直接的是看肿瘤细胞自身（单细胞层面）是否表达 GLI1，而不是看整块组织。",
