    "summary": "Wnt 通路的活性不只看配体多少，还看受体在膜上能待多久。",
    "body": "【主线】除了配体-受体-β-catenin 这条主线（见 regen-03），还有两个重要机制。第一是受体丰度调控：ZNRF3 与 RNF43 是 E3 泛素连接酶，泛素化 Frizzled 受体促其降解，等于给通路装了个「限流阀」；R-spondin（RSPO1-4）结合 LGR4/5/6，进而抑制 ZNRF3/RNF43，使 Frizzled 稳定在膜上——所以 RSPO 是强效增强剂，RSPO 融合基因（尤其 RSPO2/3 重排）在多种肿瘤中是驱动事件。第二是非经典分支：平面细胞极性通路（Wnt5a 经 ROR1/2 与 VANGL 激活 RHOA-ROCK，调控细胞骨架与迁移）与 Wnt/Ca²⁺ 通路（激活 PKC、CAMKII、NFAT），它们不依赖 β-catenin，功能偏「运动与极性」而非「转录增殖」。\n\n【关键】这两块常被忽略，但对肝癌研究很实用：一是 RNF43 突变或 RSPO 融合会造成「配体非依赖」的 Wnt 激活，此时上游 WNT 表达可能不高，但靶基因照样高；二是 Wnt5a 在肝癌中常起抑癌或促迁移的双向作用，方向取决于受体背景（ROR1 高 vs ROR2 高），一刀切地说「Wnt 促癌」会错；三是 ZNRF3/RNF43 的缺失与 CTNNB1 突变在功能上类似但不完全等同（前者还影响受体的整体周转）。\n\n【和生信分析的连接】判断 Wnt 激活要「分层看」：配体层（WNT3/3A、WNT5A）、受体调控层（RSPO2/3、RNF43、ZNRF3、LGR5）、胞内层（CTNNB1 突变、APC、AXIN1）、输出层（AXIN2、LGR5、GLUL、LECT2、TBX3）。只有输出层能说明「通路在动」，其余都是解释原因。要提醒：AXIN2 与 LGR5 是负反馈与干细胞标志，单独用会受干细胞比例影响；GLUL 虽特异但只在部分组织表达。报告时最好说明「靶基因评分升高的可能上游」，而不是直接给结论。",
