    "summary": "I 型干扰素做的事，是让细胞进入一种「全面戒备」的转录状态。",
    "body": "【主线】I 型干扰素（IFN-α/β）结合 IFNAR1/IFNAR2，激活 JAK1 与 TYK2，磷酸化 STAT1 与 STAT2；STAT1-STAT2 与 IRF9 组成 ISGF3 复合物，入核结合干扰素刺激应答元件（ISRE），启动数百个 ISG（ISG15、MX1、OAS1、IFIT1/3、BST2、CXCL10）。II 型干扰素（IFN-γ）则走 JAK1/JAK2-STAT1 同源二聚体，结合 GAS 元件，靶基因偏免疫（CXCL9/10、GBP1、IDO1、HLA 分子）。两条路的靶基因有重叠但不等同。\n\n【关键】这套系统的强度由负反馈精确控制：USP18 去除 ISG15 修饰并阻断 IFNAR 信号（这是临床上干扰素耐受的关键）；SOCS1 抑制 JAK；STAT1 本身也诱导其抑制因子。关键的病理意义是：肿瘤可通过 JAK1/2 失活突变、STAT1 缺失、或 IFNAR 下调来「对干扰素免疫」，这构成对 PD-1 抗体与放疗联合的原发耐药（见 radio-16）。另一个重要点：持续低水平 IFN 会驱动慢性炎症与免疫耗竭，这在肝炎与肝硬化背景中很常见。\n\n【和生信分析的连接】区分 I 型与 II 型干扰素签名是常见需求：I 型偏 MX1、ISG15、IFIT1/3、OAS1、BST2；II 型偏 CXCL9、CXCL10、GBP1、IDO1、HLA-DRA。但两者重叠很大，实践中更稳的是看上游（IFNB1 vs IFNG 的表达细胞来源）与功能后果（抗原呈递上调偏 II 型）。要提醒：ISG 评分高也可能来自病毒感染或 STING 激活（见 immune-09），所以「ISG 高」不是「IFN-γ 高」的同义词。做免疫治疗响应预测时，建议同时报告 IFN 签名与 JAK1/2、B2M 的突变状态。",
