    "summary": "胆汁酸不只是消化液，它还是信号分子，FXR 是它的主受体。",
    "body": "【主线】胆汁酸在肝细胞里由胆固醇经 CYP7A1（限速酶）、CYP8B1、CYP27A1 合成，经 BSEP（ABCB11）分泌入胆管，再由 ASBT（SLC10A2）在回肠末端重吸收，经门静脉回到肝脏（肠肝循环）。FXR（NR1H4）是核受体，被胆汁酸（尤其鹅去氧胆酸、胆酸）激活后做三件事：一是上调 SHP（NR0B2），抑制 CYP7A1 减少合成；二是上调 BSEP 促排泄；三是诱导 FGF19（小鼠为 FGF15），经门静脉到肝，结合 FGFR4/β-Klotho 进一步抑制 CYP7A1。\n\n【关键】FXR 的作用远超胆汁酸：它抑制肝细胞增殖、促进胆管保护、调节脂质与糖代谢（激活 FXR 可改善胰岛素敏感性）、并抑制炎症（通过拮抗 NF-κB）。这就是 FXR 激动剂（如奥贝胆酸）被开发用于原发性胆汁性胆管炎与非酒精性脂肪性肝炎的原因。副作用也来自同一机制：瘙痒（可能由 Lysophosphatidic acid 与 ATX 介导）、以及 LDL 升高。在肝癌中 FXR 表达常下调，且 FXR 缺失小鼠自发肝癌，说明它有抑癌作用（见 regen-18）。\n\n【和生信分析的连接】FXR 活性评分用靶基因（NR0B2/SHP、ABCB11、ABCG5/8、FGF19、SLC10A1、CYP7A1 反向），注意 CYP7A1 是「被抑制」的靶基因，方向与其他相反——这是个很容易搞反的地方。要点：一是胆汁酸代谢基因在肝内表达量极高，容易被测序深度主导；二是肠道 FXR 与肝脏 FXR 作用不同，组织来源必须明确；三是胆汁酸池大小受饮食与肠道菌群影响，跨个体比较时需谨慎（见 tme-09）。在 RILD 里，若 FXR 靶基因整体下降，提示胆汁酸合成去抑制，可能加重损伤。",
