    "body": "【主线】PXR（NR1I2）被一大类外源物（利福平、圣约翰草、某些农药）激活，与 RXR 异二聚化后上调 CYP3A4、ABCB1（P-gp）、UGT1A1，作用是「加快代谢与排出」；CAR（NR1I3）则被苯巴比妥类激活，上调 CYP2B6、CYP3A4、UGT1A1 以及转运体，同时促进肝细胞增殖。AhR 是 bHLH-PAS 转录因子，被二噁英、多环芳烃、色氨酸代谢物（如 FICZ、犬尿氨酸）激活，与 ARNT 组成异二聚体上调 CYP1A1/1B1、AHRR（负反馈）、以及 IL-22 等免疫基因。\n\n【关键】这三个受体的临床意义集中在药物相互作用：利福平激活 PXR 会加速口服避孕药、他汀、抗凝药的代谢，导致疗效下降；而酮康唑、葡萄柚成分抑制 CYP3A4 则相反。另一个重要点是「外源物受体也参与内源代谢与炎症」：CAR 激活抑制胆汁酸合成与胆红素代谢（这也是苯巴比妥治疗新生儿黄疸的机制）；AhR 是连接环境与免疫的桥梁，在肠道与皮肤免疫中作用显著。肝癌中 AhR 高表达常与侵袭性相关，而 PXR/CAR 的表达变化会影响化疗敏感性。\n\n【和生信分析的连接】这三个受体本身 mRNA 变化通常不大（激活靠配体结合），所以要看靶基因：PXR 看 CYP3A4、ABCB1、UGT1A1；CAR 看 CYP2B6、CYP3A4、SULT2A1；AhR 看 CYP1A1、CYP1B1、AHRR、TIPARP。要提醒三点：一是 CYP3A4 在肝内表达极高且个体差异巨大（受遗传与药物影响），跨样本比较容易被它主导；二是 AhR 靶基因与氧化应激、NF-κB 有交叉，不能只凭 CYP1A1 判断；三是这些基因的诱导是「瞬时」的，样本采集前的用药史会强烈影响结果，而临床注释里往往没有这项信息——这是一个必须写进局限的混杂因素。",
