    "body": "【主线】胰高血糖素、肾上腺素结合 GPCR（GCGR、ADRB2），经 Gs 激活腺苷酸环化酶（ADCY），把 ATP 转成 cAMP；cAMP 结合 PKA 的调节亚基，释放催化亚基，PKA 磷酸化下游底物：磷酸化酶激酶与糖原磷酸化酶（促糖原分解）、抑制糖原合成酶、磷酸化 CREB 的 Ser133 使其招募 CBP/p300 启动 PGC1A（PPARGC1A）、PCK1、G6PC（促糖异生）。终止靠磷酸二酯酶（PDE）水解 cAMP 与磷酸酶去磷酸化。\n\n【关键】这条通路的方向由 G 蛋白类型决定：Gs 升 cAMP，Gi（如 α2 肾上腺素受体、部分趋化因子受体）降 cAMP。同一配体在不同细胞上可能偶联不同 G 蛋白，效果相反。另一个关键概念是「区室化」：cAMP 信号不是均匀扩散的，PKA 通过 AKAP 锚定在特定位置，所以同一个细胞内不同区域的 cAMP 可以产生不同效果。这也解释了为什么某些药物（如 PDE 抑制剂）的效果难以预测。\n\n【和生信分析的连接】转录层面看 CREB 靶基因：PGC1A（PPARGC1A）、PCK1、G6PC、NR4A1、FOS、CREM、VGF。在肝脏课题里，这条通路的实际意义是「样本采集时的代谢状态」：禁食时间、麻醉方式、处死时间都会显著改变 PGC1A 与糖异生基因的表达——这是动物实验与人肝样本里最常见的隐性混杂之一。若看到一批样本的糖异生基因整体高或整体低，先问「取材前的进食状态是否一致」，再谈疾病效应。另外 PDE 抑制剂（如咖啡因、西地那非类）在体外实验中的浓度常远超生理，解释结果时要谨慎。",
