    "summary": "很多信号的开关不在转录，而在「这个蛋白什么时候被降解」。",
    "body": "【主线】泛素化是三级酶级联：E1 激活泛素，E2 结合并传递，E3 决定底物特异性（人类有数百个 E3，所以特异性主要在这一层）。泛素链的连接方式决定命运：K48 链主要送蛋白酶体降解，K63 链更多参与信号转导与 DNA 修复，K11 与线性链参与细胞周期与 NF-κB。蛋白酶体（26S）由 20S 核心（β1/β2/β5 催化活性）与 19S 调节颗粒组成，识别多泛素化蛋白并降解。去泛素化酶（DUB，如 USP7、USP14、CYLD、A20/TNFAIP3）负责撤销修饰。\n\n【关键】为什么这条通路在机制研究里这么重要：很多关键蛋白的「活性」根本不由 mRNA 决定——β-catenin、p53（MDM2）、HIF-1α（VHL）、IκBα、YAP、NRF2（KEAP1）全都是靠降解调控的（见 regen-03、signaling-01、tme-06）。所以看到这些基因的 mRNA 不变，绝不能推断通路没动。药物层面，蛋白酶体抑制剂（硼替佐米）用于多发性骨髓瘤，但肝毒性明显；DUB 抑制剂与 PROTAC（靶向蛋白降解）是近年热点，后者利用泛素系统主动降解特定蛋白，对小分子难以成药的靶点特别有价值。\n\n【和生信分析的连接】转录层面能看的是「泛素-蛋白酶体系统的组成」：E3 连接酶（MDM2、SKP2、FBXW7、βTrCP/BTRC、VHL、KEAP1）、DUB（USP7、USP14、CYLD、TNFAIP3）、蛋白酶体亚基（PSMB5/8/9、PSMC 家族）。若蛋白酶体亚基整体上调，提示细胞处于「蛋白毒性应激」或对蛋白酶体抑制剂敏感。但要清楚：这套系统的作用是「决定蛋白半衰期」，转录组看不到半衰期。真要研究必须用蛋白层面的实验（环己酰亚胺追踪、泛素化 IP）。这也是纯计算课题的天然边界，写作用词宜为「提示蛋白稳态通路被调动」。",
